//
//  VoiceCallManager.swift
//  OSHI - Encrypted Voice Calls
//
//  Provides encrypted P2P voice calls with real-time voice effects
//  Uses mesh network for nearby peers, VPS relay for remote peers
//
//  PRIVACY ARCHITECTURE:
//  - Mesh calls: Direct P2P, peers see each other's local network
//  - VPS calls: Both users connect to VPS relay
//    - User A sees only VPS IP
//    - User B sees only VPS IP
//    - Users DON'T see each other's IPs
//  - All audio is E2E encrypted (AES-256-GCM)
//  - VPS only sees encrypted blobs, cannot decrypt
//
//  Same VPS infrastructure as MessageManager:
//  - Public: https://oshi-messenger.com
//

import SwiftUI
import AVFoundation
import AudioToolbox
import Accelerate   // vDSP — echo suppressor gain, applied per 20 ms mic frame
import Network
import CryptoKit
import Combine
import CallKit
import os.log
import UserNotifications

// Unified logging for reliable log capture on iOS 26+
private let callLog = Logger(subsystem: "Moriceau-lab.Genesis", category: "VoiceCall")

// File-based call logger for pulling logs from device after test calls

private let fileLog = CallFileLogger.shared

// MARK: - 🎯 WHATSAPP-QUALITY AUDIO COMPONENTS

// ============================================================================
// ADAPTIVE BITRATE CONTROLLER
// ============================================================================
// Dynamically adjusts audio quality based on network conditions
// Similar to how WhatsApp/Zoom adjust video quality

class AdaptiveBitrateController {
    // Bitrate levels (samples per packet)
    enum BitrateLevel: Int, CaseIterable {
        case ultraLow = 480    // 10ms @ 48kHz - emergency mode
        case low = 720         // 15ms @ 48kHz - poor network
        case medium = 960      // 20ms @ 48kHz - normal (default)
        case high = 1440       // 30ms @ 48kHz - good network
        case ultraHigh = 1920  // 40ms @ 48kHz - excellent network

        var description: String {
            switch self {
            case .ultraLow: return "Ultra Low (10ms)"
            case .low: return "Low (15ms)"
            case .medium: return "Medium (20ms)"
            case .high: return "High (30ms)"
            case .ultraHigh: return "Ultra High (40ms)"
            }
        }

        var packetIntervalMs: Double {
            return Double(rawValue) / 48.0  // At 48kHz
        }
    }

    // Network quality tiers for RTT-based bitrate selection
    enum NetworkQuality: String {
        case good = "Good"       // <100ms RTT, <1% loss -> 80kbps
        case medium = "Medium"   // 100-200ms RTT, 1-5% loss -> 48kbps
        case bad = "Bad"         // >200ms RTT, >5% loss -> 24kbps

        var targetBitrateKbps: Int32 {
            switch self {
            case .good: return 80000
            case .medium: return 48000
            case .bad: return 24000
            }
        }
    }

    private(set) var currentLevel: BitrateLevel = .medium
    private(set) var currentNetworkQuality: NetworkQuality = .medium
    private var recentPacketLoss: [Bool] = []  // true = lost
    private var recentLatencies: [Double] = []
    private let windowSize = 50  // Analyze last 50 packets

    /// __LOSS_WINDOW_2026_09_13__ La fenêtre de PERTE est séparée, et bien plus
    /// large que celle de latence.
    ///
    /// Sur 50 paquets, `packetLossPercent` ne peut valoir que 0 %, 2 %, 4 %… — la
    /// granularité est de DEUX points. Le seuil de bascule, lui, est à 1 %. Un
    /// lien qui perd réellement 1 paquet sur 100 fait donc osciller la mesure
    /// entre 0 % et 2 % de part et d'autre du seuil, une fois par seconde environ
    /// (50 paquets à 20 ms = 1 s), et le débit du codec suit: 80 kbps ↔ 48 kbps,
    /// en boucle, tout l'appel. C'est le « métallique » entendu sur un appel P2P
    /// par ailleurs parfait — 1 % est très exactement le pire taux possible ici.
    ///
    /// 250 paquets = 5 s, soit une granularité de 0,4 %: 1 % devient une valeur
    /// représentable et non plus un battement entre deux voisines.
    private let lossWindowSize = 250

    /// User-chosen ceiling (Settings → Calls → Call Quality = Low). `nil` means no cap (Auto/High).
    var maxLevelCap: BitrateLevel?

    /// Force the current level (used by High to start at ultraHigh instead of medium).
    /// Cap still applies — High + a Low cap would clamp to the cap.
    func forceLevel(_ level: BitrateLevel) {
        let clamped = clampToCap(level)
        if clamped != currentLevel {
            currentLevel = clamped
            onBitrateChange?(clamped, 0, 0)
        }
    }

    private func clampToCap(_ level: BitrateLevel) -> BitrateLevel {
        guard let cap = maxLevelCap else { return level }
        let levelIdx = BitrateLevel.allCases.firstIndex(of: level) ?? 2
        let capIdx = BitrateLevel.allCases.firstIndex(of: cap) ?? BitrateLevel.allCases.count - 1
        return levelIdx > capIdx ? cap : level
    }

    // RTT-based quality monitoring (500ms sampling)
    private var rttSamples: [Double] = []
    private let rttWindowSize = 20  // Last 20 RTT samples (10 seconds at 500ms)

    /// Report a received packet (for loss calculation)
    func reportPacketReceived() {
        recentPacketLoss.append(false)
        trimArrays()
    }

    /// Report a lost packet
    func reportPacketLost() {
        recentPacketLoss.append(true)
        trimArrays()
        adjustLevel()
        // __LOSS_MUST_MOVE_THE_TIER_2026_08_18__
        //
        // This called `adjustLevel()` only. `adjustLevel` drives the Opus ladder;
        // `currentNetworkQuality` — the tier that sets the AAC-ELD bitrate through
        // `onNetworkQualityChange` and carries the protected 24 kbps audio floor —
        // was updated ONLY from `reportRTT`.
        //
        // So the tier was a function of round-trip time alone. A link that rots
        // through PACKET LOSS while latency stays flat (congested WiFi, a cell
        // handover) never moved it, and — worse — when the far end stops answering
        // RTT probes altogether, `reportRTT` stops being called and the tier
        // FREEZES at its last value exactly when it matters most. Audio then keeps
        // being encoded at 48 kbps for a link that cannot carry it: weak, artefacted,
        // and eventually gone. That is the App Store report of 2026-08-16 almost
        // word for word ("audio was very weak and eventually just stopped with weird
        // noises").
        //
        // `updateNetworkQuality` is idempotent and only emits on a real transition,
        // so calling it on a loss event costs nothing when nothing changed.
        updateNetworkQuality()
    }

    /// Report latency measurement
    func reportLatency(_ latencyMs: Double) {
        recentLatencies.append(latencyMs)
        trimArrays()
        adjustLevel()
    }

    /// Report an RTT sample (measured every 500ms by NetworkQualityMonitor)
    func reportRTT(_ rttMs: Double) {
        rttSamples.append(rttMs)
        while rttSamples.count > rttWindowSize {
            rttSamples.removeFirst()
        }
        updateNetworkQuality()
    }

    /// Get average RTT from recent samples
    var averageRTT: Double {
        guard !rttSamples.isEmpty else { return 0 }
        return rttSamples.reduce(0, +) / Double(rttSamples.count)
    }

    /// Get current packet loss percentage
    var packetLossPercent: Double {
        guard !recentPacketLoss.isEmpty else { return 0 }
        let lostCount = recentPacketLoss.filter { $0 }.count
        return Double(lostCount) / Double(recentPacketLoss.count) * 100
    }

    /// Get average latency
    var averageLatency: Double {
        guard !recentLatencies.isEmpty else { return 0 }
        return recentLatencies.reduce(0, +) / Double(recentLatencies.count)
    }

    /// Callback when bitrate level changes (for Opus integration)
    var onBitrateChange: ((BitrateLevel, Double, Double) -> Void)?

    /// Callback when network quality tier changes (for direct AAC-ELD bitrate control)
    var onNetworkQualityChange: ((NetworkQuality) -> Void)?

    /// Update network quality tier based on RTT + packet loss
    private func updateNetworkQuality() {
        let rtt = averageRTT
        let loss = packetLossPercent

        // __QUALITY_HYSTERESIS_2026_08_14__ Bare thresholds with no dead band.
        //
        // Measured on a clean P2P call over WiFi: RTT sat at 187–212 ms — straddling
        // the 200 ms line — and the badge flapped Bad↔Medium eight times in under a
        // minute while packet loss stayed at 0.0 % the whole call. The user heard a
        // good call and was shown "bad connection".
        //
        // Two corrections. First, a metric that decides a user-visible state needs
        // hysteresis: it now takes a clearly WORSE reading to degrade than it takes
        // to recover, so sitting on a boundary no longer oscillates. Second, loss is
        // no longer optional evidence — 200 ms with ZERO loss is a perfectly good
        // call, and calling it "bad" on latency alone is what made the badge wrong.
        // __HYSTERESIS_WAS_INVERTED_2026_09_13__ La bande morte était appliquée
        // À L'ENVERS, et le battement qu'elle devait supprimer existait toujours.
        //
        // Elle valait `.good ? 0.0 : 40.0`: ajoutée seulement lorsqu'on était DÉJÀ
        // dégradé. Résultat, en partant de « bon » il suffisait de dépasser 140 ms
        // pour tomber en « moyen », mais une fois en « moyen » il fallait dépasser
        // 180 ms pour Y RESTER. À 160 ms on obtient donc: bon → moyen → bon →
        // moyen, à chaque évaluation. La bande ne supprimait pas l'oscillation,
        // elle la DÉPLAÇAIT dans l'intervalle 140–180 ms. Le commentaire de la
        // correction du 14/08 décrit pourtant l'intention exacte — « il faut une
        // mesure clairement PIRE pour se dégrader que pour se rétablir » — c'est
        // le signe qui était faux, pas le raisonnement.
        //
        // Une hystérésis correcte veut deux seuils, celui de dégradation PLUS HAUT
        // que celui de rétablissement: on ajoute donc la bande quand on est BON
        // (il faut > 180 ms pour partir) et pas quand on est dégradé (il faut
        // repasser sous 140 ms pour revenir).
        let worse = currentNetworkQuality == .good ? 40.0 : 0.0   // dead band, ms

        // Et la même chose pour la PERTE, qui n'en avait aucune: `loss > 1` était
        // une comparaison nue. Combinée à la fenêtre de 50 paquets corrigée plus
        // haut, c'est ce qui faisait basculer le débit une fois par seconde.
        // Se dégrader demande 1,6 % ; revenir demande de repasser sous 1,0 %.
        let lossBand = currentNetworkQuality == .good ? 0.6 : 0.0  // dead band, points

        let newQuality: NetworkQuality
        if loss > 5 + lossBand || (rtt > 260 + worse && loss > 0.5) || rtt > 400 {
            newQuality = .bad
        } else if loss > 1 + lossBand || rtt > 140 + worse {
            newQuality = .medium
        } else {
            newQuality = .good
        }

        if newQuality != currentNetworkQuality {
            let oldQuality = currentNetworkQuality
            currentNetworkQuality = newQuality
            fileLog.log("RTT Quality: \(oldQuality.rawValue) -> \(newQuality.rawValue) (RTT: \(String(format: "%.0f", rtt))ms, loss: \(String(format: "%.1f", loss))%)")
            onNetworkQualityChange?(newQuality)
        }
    }

    /// Adjust bitrate level based on conditions
    private func adjustLevel() {
        let loss = packetLossPercent
        let latency = averageLatency

        // Decision matrix
        var newLevel: BitrateLevel

        if loss > 15 || latency > 500 {
            newLevel = .ultraLow
        } else if loss > 10 || latency > 300 {
            newLevel = .low
        } else if loss > 5 || latency > 200 {
            newLevel = .medium
        } else if loss > 2 || latency > 100 {
            newLevel = .high
        } else {
            newLevel = .ultraHigh
        }

        // User-set ceiling (e.g. Call Quality = Low) — never exceed.
        newLevel = clampToCap(newLevel)

        // Only change level if significantly different (prevents oscillation)
        if newLevel != currentLevel {
            let oldIndex = BitrateLevel.allCases.firstIndex(of: currentLevel) ?? 2
            let newIndex = BitrateLevel.allCases.firstIndex(of: newLevel) ?? 2

            // Allow downgrade immediately, but upgrade slowly
            if newIndex < oldIndex {
                currentLevel = newLevel
                OshiLog.call.info("Adaptive Bitrate: Downgraded to \(newLevel.description) (loss: \(String(format: "%.1f", loss))%, latency: \(String(format: "%.0f", latency))ms)")
                onBitrateChange?(newLevel, loss, latency)
            } else if recentPacketLoss.count >= lossWindowSize {
                // Only upgrade after full window of good data
                currentLevel = newLevel
                OshiLog.call.info("Adaptive Bitrate: Upgraded to \(newLevel.description) (loss: \(String(format: "%.1f", loss))%, latency: \(String(format: "%.0f", latency))ms)")
                onBitrateChange?(newLevel, loss, latency)
            }
        }
    }

    private func trimArrays() {
        while recentPacketLoss.count > lossWindowSize {
            recentPacketLoss.removeFirst()
        }
        while recentLatencies.count > windowSize {
            recentLatencies.removeFirst()
        }
    }
    
    func reset() {
        currentLevel = .medium
        currentNetworkQuality = .medium
        recentPacketLoss.removeAll()
        recentLatencies.removeAll()
        rttSamples.removeAll()
    }
}

// ============================================================================
// NETWORK QUALITY MONITOR
// ============================================================================
// Measures RTT every 500ms by timestamping sent packets and comparing with acks.
// Feeds RTT + packet loss into AdaptiveBitrateController for dynamic bitrate.

class NetworkQualityMonitor {
    private var rttTimer: DispatchSourceTimer?
    private let queue = DispatchQueue(label: "NetworkQualityMonitor", qos: .userInteractive)
    private var sentTimestamps: [UInt64: Date] = [:]  // packetSeq -> sentTime
    private var nextProbeSeq: UInt64 = 0
    private var lock = NSLock()

    /// Called by VoiceCallManager when a packet is sent — records timestamp
    func recordSent(sequenceNumber: UInt64) {
        lock.lock()
        sentTimestamps[sequenceNumber] = Date()
        // Evict old entries (keep last 200)
        if sentTimestamps.count > 200 {
            let sortedKeys = sentTimestamps.keys.sorted()
            for key in sortedKeys.prefix(sentTimestamps.count - 200) {
                sentTimestamps.removeValue(forKey: key)
            }
        }
        lock.unlock()
    }

    /// Called when an ack/response is received for a sent packet — computes RTT
    func recordReceived(sequenceNumber: UInt64, bitrateController: AdaptiveBitrateController) {
        lock.lock()
        guard let sentTime = sentTimestamps[sequenceNumber] else {
            lock.unlock()
            return
        }
        sentTimestamps.removeValue(forKey: sequenceNumber)
        lock.unlock()

        let rttMs = Date().timeIntervalSince(sentTime) * 1000.0
        bitrateController.reportRTT(rttMs)
    }

    /// Start periodic 500ms RTT probing using ping sequence matching
    func start(sendProbe: @escaping () -> Void) {
        stop()
        let timer = DispatchSource.makeTimerSource(queue: queue)
        timer.schedule(deadline: .now(), repeating: .milliseconds(500))
        timer.setEventHandler { sendProbe() }
        timer.resume()
        rttTimer = timer
    }

    func stop() {
        rttTimer?.cancel()
        rttTimer = nil
        lock.lock()
        sentTimestamps.removeAll()
        lock.unlock()
    }
}

// ============================================================================
// ADAPTIVE JITTER BUFFER (cross-platform — mirrors Android AudioJitterBuffer.kt)
// ============================================================================
// Per CALL_V2_PLAN Component B:
// - Target depth starts at 60 ms.
// - Inter-arrival jitter tracked via RFC 3550: J += (|D(i,i-1)| - J) / 16
//   where D is the deviation of actual vs expected inter-arrival time.
// - On a late arrival (packet's playback slot has already been consumed):
//   widen target to max(current, 4*J, 4*lateness_ms), clamped to [60, 800] ms.
// - On >=3 consecutive real losses (slot advances with no packet available):
//   jump target to min(current * 2, 800) — burst-loss escalation, so we don't
//   wait for 4*J smoothing to catch up to a sudden burst (audible pumping).
// - On 8 consecutive 1-second windows without a late arrival and J < 10 ms:
//   shrink target by 10 ms/s, floored at 60 ms. The 8 s window (previously 3 s)
//   avoids shrinking prematurely and re-expanding on the next loss burst.
// - Expand is instant, shrink is gradual — NetEQ-style asymmetric.
// - Keeps PLC unchanged; caller uses PacketLossConcealer on the returned data.

class AdvancedJitterBuffer {
    struct BufferedPacket {
        let sequenceNumber: UInt64
        let timestamp: Date
        let audioData: Data
    }

    // Configuration. Tuning history:
    //  - Was 800 ms / 8 s windows / 10 ms/s — defensive values from the old
    //    TCP-mesh fallback era; left depth pinned high for minutes after one
    //    loss burst, adding perceptible delay.
    //  - Tried 400 ms / 3 windows / 20 ms/s — too tight; chronic underrun when
    //    the network briefly bumped J above stability threshold, audible as
    //    the same metallic chop we were trying to fix.
    //  - Current values are the compromise that mirrors Android's tuning.
    private let packetDurationMs: Double = 20
    // 🔧 1.0.21 (Option A — audio fluidity): bumped from 60→80 (min) and
    // 60→120 (initial). 2026-06-10: bumped again to 180 ms initial after
    // user reported small remaining "grésillement" on cellular calls
    // (PLC still engaging on the first few seconds before the adaptive
    // expansion catches up). 180 ms cleanly covers the 95th-percentile
    // 5G jitter (~70 ms) plus the 4×J safety margin without exceeding the
    // 200 ms conversational perception threshold.
    private let minDepthMs: Int = 80
    private let maxDepthMs: Int = 600
    private let initialTargetDepthMs: Int = 180
    private let expandJitterMultiplier: Int = 4
    private let shrinkStepMs: Int = 15
    private let shrinkWindowMs: Double = 1000
    private let shrinkStableWindows: Int = 5
    private let shrinkJitterThresholdMs: Double = 10.0

    /// __JITTER_RATCHET_2026_08_25__ De combien la profondeur doit dépasser son
    /// propre plancher de rafale avant qu'on la laisse redescendre, même quand
    /// la gigue lissée ne dit pas « calme ».
    ///
    /// Généreux à dessein. Un appel sain se pose quelques dizaines de ms
    /// au-dessus de son plancher et ne doit JAMAIS déclencher ça — sinon on
    /// rallonge des appels qui vont bien. L'appel qui a motivé le correctif
    /// flottait 263 ms au-dessus du sien (589 contre un gapTarget de 326).
    private let overshootReleaseMs: Int = 120
    private let burstLossThreshold: Int = 3

    // 🔧 FIX (2026-08-10, Natalia calls — choppy audio on a relayed link):
    //
    // MEASURED on the 16:14:53 call (105 s, 5093/5110 packets delivered — 99.7 %,
    // so this was NEVER loss): `targetDepthMs=180` for the ENTIRE call while
    // `iaP95Ms=85.4` and `iaMaxMs` peaked at 254 / 291 / 327 ms.
    //
    // Every expansion path above is driven by `networkJitterMs` — the RFC 3550
    // estimate, an exponentially-weighted mean over |deviation|. A mean is
    // structurally blind to bursts: 50 arrivals at 20 ms and one at 327 ms read
    // as J≈18. The estimator concluded the link was calm while the pipeline was
    // being asked to cover a third of a second with 180 ms of audio. It
    // underran, PLC filled the hole, and that is the chop.
    //
    // The other two expansion paths could not save it either. `recordLateArrival`
    // needs a packet to arrive after its slot played — but a BURST arrives in
    // order, just all at once, so nothing is late. `consecutiveLosses` needs
    // empty slots, and the packets were not lost, only bunched.
    //
    // So: measure the quantity that actually matters. Each arrival hands the
    // pipeline 20 ms of audio while wall-clock consumes `actualDelta` ms, so a
    // gap DRAINS `actualDelta - 20` ms of depth. To ride out a gap the buffer
    // must be at least that deep. Track those drains and size the buffer off a
    // high percentile of them, not off a mean.
    //
    // A PEAK DETECTOR, not a percentile. The first attempt sized off P95 of the
    // drain window and did not expand at all — correctly, and the tests caught
    // it. Stalls are RARE by count: one stall per 50 arrivals is 2 % of samples,
    // so the 95th percentile lands in the calm region and reports nothing wrong.
    // The very property that makes a burst hurt — infrequent but large — is what
    // hides it from any percentile low enough to be robust.
    //
    // So track the peaks themselves, the way WebRTC's NetEq does. A drain past
    // `peakThresholdMs` is recorded with its timestamp; peaks older than
    // `peakWindowMs` expire. Once at least `peakMinCount` live peaks have piled
    // up, the link is REPEATEDLY stalling and the buffer is sized off the largest
    // of them.
    //
    // Requiring two peaks is what separates a bursty link from a one-off hiccup:
    // a single lift or handover expires without ever costing latency, while a
    // relay that stalls over and over gets the depth it needs. And because peaks
    // expire, a link that calms down gets its latency back instead of staying
    // pinned deep for the rest of the call.
    static var burstDepthEnabled: Bool = !UserDefaults.standard.bool(forKey: "OSHIAudioDisableBurstDepth")
    private let peakThresholdMs: Double = 80     // = minDepthMs; a 20 ms cadence stalling this long is abnormal
    private let peakWindowMs: Double = 20_000
    private let peakMinCount: Int = 2
    private let peakMaxTracked: Int = 16
    private let gapMarginMs: Int = 40            // headroom above the largest live peak
    /// __CALM_EXPIRES_THE_EVIDENCE_2026_08_27__ Arrivées consécutivement CALMES
    /// après lesquelles on retire le plus ANCIEN pic.
    ///
    /// Les pics expirent déjà, mais seulement au bout de `peakWindowMs` = 20 s,
    /// que le lien se soit rétabli ou non. MESURÉ après un trou réseau d'environ
    /// 4 s le 27 août:
    ///
    ///     10:21:06   iaP95 = 255 ms   cible = 600 ms   (légitime)
    ///     10:21:08   iaP95 = 149 ms   cible = 600 ms   ← le lien est revenu
    ///     10:21:12   iaP95 =  96 ms   cible = 600 ms
    ///     10:21:18   iaP95 =  96 ms   cible = 600 ms
    ///     10:21:24   iaP95 =  84 ms   cible = 600 ms
    ///     10:21:26   ...              cible = 296 ms   ← enfin, 18 s trop tard
    ///
    /// Le lien était sain en DEUX secondes; la latence est restée à 600 ms
    /// pendant VINGT. C'est ce qu'on entend comme un appel qui « met du temps à
    /// redevenir normal » après une coupure. Et le rogneur de file, ancré sur
    /// cette cible, refusait d'aider puisqu'il la croyait justifiée.
    ///
    /// UNE PREMIÈRE TENTATIVE A ÉCHOUÉ, et les tests l'ont attrapée: fusionner
    /// les pics d'un même incident. Mais `JitterBufferDecayTests` injecte trois
    /// décrochages à 500 ms d'intervalle et exige que la profondeur MONTE — et
    /// il a raison, un lien qui stalle trois fois en une seconde et demie est
    /// vraiment mauvais. Compter moins de pics cassait la protection contre la
    /// famine.
    ///
    /// Ce n'est donc pas le COMPTAGE qu'il faut changer, c'est l'EXPIRATION: une
    /// preuve que le présent contredit ne doit pas garder 20 secondes de crédit.
    /// 100 arrivées calmes ≈ 2 s à 50 paquets/s, et chacune de ces fenêtres rend
    /// un pic. Un lien qui reste mauvais n'accumule aucune arrivée calme et garde
    /// toute sa profondeur.
    private let calmArrivalsToExpireOnePeak: Int = 100
    /// Une arrivée est CALME sous cette fraction du seuil de pic. Il ne suffit
    /// pas d'être sous le seuil: il faut en être loin, sinon un lien qui frôle
    /// le seuil se ferait créditer d'un calme qu'il n'a pas.
    private let calmDrainFraction: Double = 0.5
    private var calmArrivalRun: Int = 0
    private var peakDrains: [(ms: Double, atMs: Double)] = []
    /// Depth the observed burstiness justifies. Also the floor for shrinking —
    /// without that floor the existing shrink path, gated on the same blind mean,
    /// would walk this expansion straight back down while the bursts continue.
    private(set) var gapBasedTargetMs: Int = 0

    // Packet storage (seq -> packet). Map lookup is O(1) which matches the
    // Android PriorityBlockingQueue's amortised behaviour.
    private var buffer: [UInt64: BufferedPacket] = [:]

    // Core state
    private var firstArrivalSeen: Bool = false
    private var lastPlayedSequence: UInt64 = 0
    private var lastPlayedValid: Bool = false
    // Next slot the consumer will play. Advances when a real packet is popped
    // OR when at least one packet-duration has elapsed since the last advance
    // (wall-clock rate-limiting, so the iOS drain loop — which may fire faster
    // than real-time — doesn't run past legitimately reordered packets).
    // A real arrival with seq below this is "late" — its slot has already
    // been played.
    private var nextSlotSequence: UInt64 = 0
    private var lastSlotAdvanceMs: Double = 0
    private var consecutiveLosses: Int = 0
    private var totalPacketsPlayed: UInt64 = 0

    // Adaptive depth state
    private var currentDepthMs: Int
    private var networkJitterMs: Double = 0.0
    private var lastArrivalSeq: Int64 = -1
    private var lastArrivalTimeMs: Double = 0

    // Shrink-window accounting
    private var windowStartMs: Double = 0
    private var stableWindows: Int = 0
    private var lateInCurrentWindow: Bool = false

    // Thread safety — serial lock, same role as Android's synchronized.
    private var lock = NSLock()

    // Clock — injectable for tests. Returns ms since start.
    var clock: () -> Double = { Date().timeIntervalSince1970 * 1000.0 }

    // Statistics (exposed for stats/diag)
    private(set) var packetsReceived: UInt64 = 0
    private(set) var packetsLate: UInt64 = 0
    private(set) var packetsReordered: UInt64 = 0
    // DIAG_JITTER_JUMP — incremented each time the slot-lag fast-forward fires.
    // Read by VoiceCallManager's once-per-second DIAG_PLAYBACK_RATE emitter.
    private(set) var totalSlotJumps: UInt64 = 0

    // 🔧 FIX (2026-07-27, chop): number of times getNextPacket() advanced the
    // slot with NOTHING to play — i.e. a genuine hole in the timeline. This is
    // the ONLY condition under which the caller may inject a concealment frame.
    // Before this counter existed the caller used `!playedAny && depth == 0`,
    // which is ALSO true when an arrival simply came too early/late to move the
    // slot — so concealment frames were spliced into slots that were never lost.
    // MEASURED on the 14:27 d14 call: 50 wire packets/s in, 65 buffers/s
    // scheduled on the player node (DIAG_SNAP sent=50/s vs played=65/s on BOTH
    // devices) — ~30 % of playback was phantom audio.
    private(set) var totalLossAdvances: UInt64 = 0

    /// Read `totalLossAdvances` under the buffer's own lock.
    ///
    /// 🔴 FIX (2026-08-20) — CONFIRMED CRASH, SEVEN TIMES.
    /// `OSHI-2026-08-14-150232.ips` and six others going back to build 84:
    /// `EXC_BREAKPOINT` / `SIGTRAP` on thread `com.oshi.p2p.transport`, inside
    /// `VoiceCallManager.processReceivedAudioData(_:sequenceNumber:)`.
    ///
    /// That function measured holes as a difference across the drain loop:
    ///
    ///     let before = advancedJitterBuffer.totalLossAdvances
    ///     while let p = advancedJitterBuffer.getNextPacket() { play(p) }
    ///     let holes = advancedJitterBuffer.totalLossAdvances - before
    ///
    /// `reset()` sets this counter back to ZERO, and it is called from eight
    /// places — including the peer's `resyncRequest` handler and the local
    /// auto-resync, neither of which runs on the transport queue. Land a reset
    /// inside that `while` loop and the last line is `0 - 4127` on a `UInt64`.
    /// Swift traps on unsigned overflow: instant, unconditional crash, on the
    /// exact thread the reports name.
    ///
    /// It is not a rare interleaving either — a resync is REQUESTED when audio is
    /// already struggling, which is when packets are pouring through that loop.
    var lossAdvancesSnapshot: UInt64 {
        lock.lock(); defer { lock.unlock() }
        return totalLossAdvances
    }

    // 🔧 FIX (2026-07-27, chop): raw wall-clock inter-arrival deltas, so the
    // next call can prove whether the chop is bursty egress (clumps + gaps →
    // TCP head-of-line blocking on the WS relay) or client mis-pacing.
    // Drained once per second by DIAG_JITTER.
    private var interArrivalSamples: [Double] = []
    private let interArrivalMaxSamples = 512

    init() {
        // 🔧 1.0.21: matches the new initialTargetDepthMs (180 ms).
        self.currentDepthMs = 180
    }

    /// Current adaptive target depth in ms. Exposed for diag logs.
    var targetDepthMs: Int {
        lock.lock(); defer { lock.unlock() }
        return currentDepthMs
    }

    /// Current smoothed RFC 3550 jitter estimate in ms.
    var jitterEstimateMs: Double {
        lock.lock(); defer { lock.unlock() }
        return networkJitterMs
    }

    /// Add a packet to the buffer.
    /// Returns true if accepted, false if duplicate or late.
    /// __DUPLICATE_IS_NOT_LOSS_2026_08_27__ Pourquoi le dernier `addPacket` a
    /// refusé. `Bool` seul ne pouvait pas le dire, et l'appelant traitait donc
    /// TOUS les refus comme des pertes.
    enum RejectReason {
        case none        // accepté
        case duplicate   // déjà reçu — le réseau en a livré PLUS, pas moins
        case late        // le consommateur est déjà passé: une vraie perte
    }
    private(set) var lastRejectReason: RejectReason = .none

    func addPacket(sequenceNumber: UInt64, audioData: Data) -> Bool {
        lock.lock()
        defer { lock.unlock() }

        lastRejectReason = .none
        packetsReceived += 1
        let now = clock()

        if !firstArrivalSeen {
            firstArrivalSeen = true
            nextSlotSequence = sequenceNumber
        }

        // Duplicate
        if buffer[sequenceNumber] != nil { lastRejectReason = .duplicate; return false }
        if lastPlayedValid && sequenceNumber == lastPlayedSequence {
            lastRejectReason = .duplicate
            return false
        }

        // RFC 3550 jitter update based on inter-arrival deviation. Runs for
        // every arrival (including late ones) so J reflects real network
        // jitter regardless of whether the packet gets buffered.
        if lastArrivalSeq >= 0 {
            let seqDelta = Int64(sequenceNumber) - lastArrivalSeq
            let expectedDelta = Double(seqDelta) * packetDurationMs
            let actualDelta = now - lastArrivalTimeMs
            let d = actualDelta - expectedDelta
            let absD = d < 0 ? -d : d
            networkJitterMs += (absD - networkJitterMs) / 16.0
            // Raw arrival spacing, independent of sequence numbers — this is
            // what shows burstiness. A steady 50 pps stream reads mean≈20 /
            // p95≈25; a TCP-relayed one reads mean≈20 but p95/max in the
            // hundreds with a pile of near-zero deltas (the burst drain).
            if interArrivalSamples.count < interArrivalMaxSamples {
                interArrivalSamples.append(actualDelta)
            }
            // Burst-aware depth. See `burstDepthEnabled` for why the smoothed
            // estimator above cannot do this job.
            if Self.burstDepthEnabled {
                recordArrivalDrain(actualDelta - packetDurationMs, now: now)
            }
        }
        lastArrivalSeq = Int64(sequenceNumber)
        lastArrivalTimeMs = now

        // Late arrival — consumer has already advanced past this seq.
        if sequenceNumber < nextSlotSequence {
            packetsLate += 1
            let latenessMs = Double(nextSlotSequence - sequenceNumber) * packetDurationMs
            // Feed lateness into J so the smoothed estimator reflects the real
            // scheduling deviation (the RFC 3550 formula on its own barely
            // moves under loss because expected_delta already accounts for
            // missing seq numbers).
            networkJitterMs += (latenessMs - networkJitterMs) / 16.0
            recordLateArrival(latenessMs: latenessMs)
            lastRejectReason = .late
            return false
        }

        if sequenceNumber > nextSlotSequence {
            packetsReordered += 1
        }

        buffer[sequenceNumber] = BufferedPacket(
            sequenceNumber: sequenceNumber,
            timestamp: Date(),
            audioData: audioData
        )

        maybeAdaptDepth(now: now)
        return true
    }

    /// Record how much playout depth one arrival gap drained, and re-size the
    /// target off a high percentile of the recent window.
    ///
    /// Called with the lock HELD (from addPacket).
    private func recordArrivalDrain(_ drainMs: Double, now: Double) {
        // Drop peaks that have aged out FIRST, so a link that calmed down starts
        // giving latency back even during a long silent stretch with no new
        // peaks to trigger a recompute.
        if !peakDrains.isEmpty {
            peakDrains.removeAll { now - $0.atMs > peakWindowMs }
        }

        // A negative drain is a packet arriving EARLY — the other half of a
        // burst, adding depth back. It is not a stall and must never be recorded
        // as one.
        // __CALM_EXPIRES_THE_EVIDENCE_2026_08_27__ Un lien qui se tient rend sa
        // latence sans attendre les 20 s de la fenêtre. On retire le plus ANCIEN
        // pic: c'est celui que le présent contredit depuis le plus longtemps.
        if drainMs < peakThresholdMs * calmDrainFraction {
            calmArrivalRun += 1
            if calmArrivalRun >= calmArrivalsToExpireOnePeak, !peakDrains.isEmpty {
                calmArrivalRun = 0
                if let oldest = peakDrains.indices.min(by: { peakDrains[$0].atMs < peakDrains[$1].atMs }) {
                    peakDrains.remove(at: oldest)
                }
            }
        } else if drainMs > peakThresholdMs {
            // Un vrai décrochage annule le crédit de calme accumulé.
            calmArrivalRun = 0
        }

        if drainMs > peakThresholdMs {
            peakDrains.append((ms: drainMs, atMs: now))
            // Keep the largest, not the newest: the whole point is the worst case
            // the link imposed inside the window.
            if peakDrains.count > peakMaxTracked {
                peakDrains.sort { $0.ms > $1.ms }
                peakDrains.removeLast(peakDrains.count - peakMaxTracked)
            }
        }

        guard peakDrains.count >= peakMinCount else {
            // One peak, or none. Not evidence of a bursty link — leave the depth
            // alone and let the normal shrink path own it.
            gapBasedTargetMs = 0
            return
        }

        let worst = peakDrains.map(\.ms).max() ?? 0
        gapBasedTargetMs = min(maxDepthMs, max(minDepthMs, Int(worst) + gapMarginMs))

        // Expand only. Shrinking stays on the existing slow, hysteretic path so
        // depth cannot oscillate audibly; `gapBasedTargetMs` becomes its floor.
        if gapBasedTargetMs > currentDepthMs {
            currentDepthMs = gapBasedTargetMs
            stableWindows = 0
        }
    }

    /// Fast-expand on late arrival.
    private func recordLateArrival(latenessMs: Double) {
        lateInCurrentWindow = true
        stableWindows = 0
        let jBased = Int(networkJitterMs * Double(expandJitterMultiplier))
        let lateBased = Int(latenessMs) * expandJitterMultiplier
        let target = max(currentDepthMs, max(jBased, lateBased))
        currentDepthMs = min(maxDepthMs, max(minDepthMs, target))
    }

    /// Close 1-second windows and slow-shrink target when the stream stabilises.
    private func maybeAdaptDepth(now: Double) {
        if windowStartMs == 0 {
            windowStartMs = now
            return
        }
        if now - windowStartMs < shrinkWindowMs { return }

        // __JITTER_RATCHET_2026_08_25__ La porte d'origine est INTACTE. On lui
        // ajoute une soupape, et seulement pour la pathologie observée.
        //
        // Mesuré sur un appel réel de 15 min (396 relevés DIAG_JITTER): médiane
        // de J = 25,3 ms, p05 = 21,7 ms, et six relevés seulement sous le seuil
        // de 10 ms — tous les six égaux à 0,0, l'estimateur avant qu'il ait la
        // moindre donnée. Une fois chauffé, J n'est jamais redescendu sous le
        // seuil: la branche ci-dessous ne s'est pas exécutée une seule fois.
        // La profondeur est montée 201 → 381 → 589 ms et y est restée, laissant
        // l'utilisateur ~0,7 s derrière sur un lien à 26 ms.
        //
        // ⚠️ J'ai d'abord remplacé cette porte par une porte relative. Ça a
        // cassé DEUX pins préexistants, et les deux avaient raison:
        //   • `testTheRealWorkingCallIsNotTouched` — un appel déjà sain finissait
        //     à 165 ms au lieu de 105: j'ajoutais de la latence à des appels qui
        //     n'ont aucun problème, le faux gain exact que ce harnais existe
        //     pour attraper.
        //   • `testDepthStaysAtTheStartingValueWithoutTheFix` — desserrer la
        //     porte retire la dernière protection du chemin sans `burstDepth`,
        //     ce que le commentaire ci-dessous annonçait déjà: la moyenne lissée
        //     lit « calme » PENDANT une rafale.
        //
        // D'où cette forme: rien n'est retiré, on ajoute une sortie qui ne
        // s'ouvre que quand la profondeur dépasse très largement son PROPRE
        // plancher — celui que la burstiness observée exige. Un appel sain se
        // pose à quelques dizaines de ms au-dessus du sien et ne la déclenche
        // jamais; celui d'Hugo flottait 263 ms au-dessus.
        //
        // Réservée au chemin de production (`burstDepthEnabled`), parce que
        // c'est le plancher de rafale qui rend une décrue sûre: sans lui, rien
        // n'arrête la descente dans la zone qui hache.
        let burstFloorMs = Self.burstDepthEnabled ? max(minDepthMs, gapBasedTargetMs) : minDepthMs
        let farAboveOwnFloor = Self.burstDepthEnabled
            && currentDepthMs - burstFloorMs > overshootReleaseMs

        if !lateInCurrentWindow && (networkJitterMs < shrinkJitterThresholdMs || farAboveOwnFloor) {
            stableWindows += 1
            if stableWindows >= shrinkStableWindows {
                // Floor the shrink at the depth observed burstiness justifies.
                // This gate is the whole point: the condition guarding this
                // branch is `networkJitterMs < shrinkJitterThresholdMs`, the very
                // mean that reads "calm" during a burst. Without the floor the
                // shrink would undo the burst expansion within a few windows and
                // the buffer would settle right back at the depth that chops.
                currentDepthMs = max(burstFloorMs, currentDepthMs - shrinkStepMs)
                stableWindows = shrinkStableWindows
            }
        } else {
            stableWindows = 0
        }
        lateInCurrentWindow = false
        windowStartMs = now
    }

    /// Get the next packet for playback.
    /// - Returns the queued packet for the current slot, if any.
    /// - If the slot is empty but at least one packet-duration has passed
    ///   since the last advance, advances the slot and returns nil (caller
    ///   should run PLC / play silence).
    /// - If the slot is empty and we're still inside a packet-duration
    ///   window, returns nil WITHOUT advancing — so a reordered packet
    ///   arriving slightly late can still slot in.
    func getNextPacket() -> Data? {
        lock.lock()
        defer { lock.unlock() }

        let now = clock()

        // Priming: on the very first call, wait until the target depth is
        // queued. After we've played anything, we never re-prime without an
        // explicit reset().
        //
        // 🔧 FIX (2026-07-27, chop): this used to prime to HALF the target
        // (180/20/2 = 4 packets = 80 ms). Playback here is arrival-driven —
        // the drain loop runs on every arrival and empties the buffer, so
        // `depthPackets` is 0 by construction and this one-shot prime is the
        // ONLY thing that ever puts depth into the pipeline. The depth then
        // lives in AVAudioPlayerNode's scheduled queue, which is the real
        // jitter buffer. Priming to half the target means the pipeline starts
        // 100 ms shallower than the adaptive estimator asked for, and it can
        // never recover it (no re-prime without reset). Prime to the full
        // target so the player queue starts at the depth the estimator sized.
        if totalPacketsPlayed == 0 {
            let divisor = VoiceCallManager.playoutFixEnabled ? 1 : 2
            let primePackets = max(1, currentDepthMs / Int(packetDurationMs) / divisor)
            if buffer.count < primePackets { return nil }
        }

        // Slot-lag fast-forward: if the lowest buffered sequence number is far
        // ahead of the slot, the peer's stream has run past us (burst loss,
        // network reordering, or a restart after we primed). Walking forward
        // one slot per tick would never catch up to a 50 pps stream — the gap
        // stays constant while packets pile up in the buffer unread. Jump the
        // slot to the lowest buffered seq. Mirrors the Android fix.
        if nextSlotSequence > 0, !buffer.isEmpty, let minBufferedSeq = buffer.keys.min() {
            let lag = Int64(minBufferedSeq) - Int64(nextSlotSequence)
            if lag > 25 {  // 25 packets × 20 ms = 500 ms — well inside our 800 ms max depth
                let oldSlot = nextSlotSequence
                totalSlotJumps += 1
                // WHY: DIAG_JITTER_JUMP — fires on every slot-lag fast-forward. If this appears
                // repeatedly on a single call, the jitter buffer is being starved or the network
                // is reordering huge bursts. skipped = lag - 1 packets voided between oldSlot
                // and minBufferedSeq.
                let line = "DIAG_JITTER_JUMP | oldSlot=\(oldSlot) | newSlot=\(minBufferedSeq) | lag=\(lag) | skipped=\(lag - 1) | bufferDepth=\(buffer.count) | totalJumps=\(totalSlotJumps) | J=\(String(format: "%.1f", networkJitterMs)) | depthMs=\(currentDepthMs)"
                OshiLog.call.info("\(line)"); CallFileLogger.shared.log(line)
                nextSlotSequence = minBufferedSeq
                consecutiveLosses = 0
            }
        }

        // Case 1: the slot we want to play is available — pop it.
        if let packet = buffer[nextSlotSequence] {
            buffer.removeValue(forKey: nextSlotSequence)
            lastPlayedSequence = nextSlotSequence
            lastPlayedValid = true
            nextSlotSequence += 1
            lastSlotAdvanceMs = now
            consecutiveLosses = 0
            totalPacketsPlayed += 1
            return packet.audioData
        }

        // Case 2: buffer empty or only has future packets. Only advance if
        // a full packet-duration has elapsed since the last advance.
        let canAdvance = lastSlotAdvanceMs == 0 ||
            (now - lastSlotAdvanceMs) >= packetDurationMs
        if !canAdvance { return nil }

        nextSlotSequence += 1
        lastSlotAdvanceMs = now
        consecutiveLosses += 1
        // A slot went by with nothing in it — a REAL hole. This is the only
        // event that entitles the caller to inject a concealment frame.
        totalLossAdvances &+= 1

        // Burst-loss escalation: on >=3 consecutive real losses, jump the
        // target depth immediately to min(current * 2, maxDepthMs). Waiting
        // for the 4*J smoothing to catch up causes audible pumping when a
        // burst hits — this pre-empts it. Reset shrink-stability so we don't
        // immediately start shrinking back.
        if consecutiveLosses >= burstLossThreshold {
            let escalated = min(maxDepthMs, currentDepthMs * 2)
            if escalated > currentDepthMs {
                currentDepthMs = max(minDepthMs, escalated)
            }
            stableWindows = 0
            lateInCurrentWindow = true
        }
        return nil
    }

    /// True when `seq` is a slot the consumer still needs and nothing is
    /// queued for it yet — i.e. injecting a recovered copy of it is useful.
    ///
    /// 🔧 FIX (2026-07-27, chop): the inline-redundancy path used to insert the
    /// piggy-backed previous frame unconditionally. Two consequences: (a) before
    /// the first real arrival it was the packet that defined `nextSlotSequence`,
    /// so the very first thing played on every call was a redundancy copy; and
    /// (b) it inserted for slots that were merely reordered, not lost. Ask first.
    func needsPacket(_ seq: UInt64) -> Bool {
        lock.lock(); defer { lock.unlock() }
        guard firstArrivalSeen else { return false }
        if seq < nextSlotSequence { return false }
        if lastPlayedValid && seq == lastPlayedSequence { return false }
        return buffer[seq] == nil
    }

    /// Snapshot + clear the raw inter-arrival window. Returns milliseconds.
    func drainInterArrivalStats() -> (mean: Double, p95: Double, max: Double, count: Int) {
        lock.lock(); defer { lock.unlock() }
        let s = interArrivalSamples
        interArrivalSamples.removeAll(keepingCapacity: true)
        guard !s.isEmpty else { return (0, 0, 0, 0) }
        let sorted = s.sorted()
        let mean = s.reduce(0, +) / Double(s.count)
        let p95Idx = min(sorted.count - 1, Int(Double(sorted.count) * 0.95))
        return (mean, sorted[p95Idx], sorted[sorted.count - 1], s.count)
    }

    /// __RX_REJECTS_IN_DIAG_2026_09_27__ Received / late / reordered, read under
    /// the lock for DIAG_JITTER. The 27/09 Natalia call (79D7B7B3) scheduled one
    /// buffer per arrival but ~43 % of them were PLC — i.e. arrivals the buffer
    /// refused — and nothing in the log said whether they were late or reordered.
    var rejectSnapshot: (received: UInt64, late: UInt64, reordered: UInt64) {
        lock.lock(); defer { lock.unlock() }
        return (packetsReceived, packetsLate, packetsReordered)
    }

    // Back-compat alias: some callers use .bufferDepthPackets
    var bufferDepthPackets: Int {
        lock.lock(); defer { lock.unlock() }
        return buffer.count
    }

    var bufferDepthMs: Double {
        return Double(bufferDepthPackets) * packetDurationMs
    }

    func reset() {
        lock.lock()
        defer { lock.unlock() }
        buffer.removeAll()
        firstArrivalSeen = false
        lastPlayedSequence = 0
        lastPlayedValid = false
        nextSlotSequence = 0
        lastSlotAdvanceMs = 0
        consecutiveLosses = 0
        totalPacketsPlayed = 0
        currentDepthMs = initialTargetDepthMs
        networkJitterMs = 0
        lastArrivalSeq = -1
        lastArrivalTimeMs = 0
        windowStartMs = 0
        stableWindows = 0
        lateInCurrentWindow = false
        packetsReceived = 0
        packetsLate = 0
        packetsReordered = 0
        totalSlotJumps = 0
        totalLossAdvances = 0
        interArrivalSamples.removeAll(keepingCapacity: true)
        peakDrains.removeAll(keepingCapacity: true)
        gapBasedTargetMs = 0
    }
}

// ============================================================================
// PACKET LOSS CONCEALER (PLC)
// ============================================================================
// Hides packet loss by interpolating/repeating audio

class PacketLossConcealer {
    private var lastGoodPacket: Data?
    private var lastGoodSamples: [Float]?
    private var consecutiveLosses = 0
    // 🔧 1.0.21 b52: bumped 3→8 (was 60ms of concealment, now 160ms). Why:
    // typical network blips on cellular last 80-200ms (a cell tower handoff
    // or brief packet loss burst); with maxConcealmentPackets=3 the listener
    // would drop to comfort noise after just 60ms, which is the abrupt
    // "the call cut" perception. 8 frames lets us ride a 160ms blip
    // entirely on pitch-cycled concealment, so a momentary glitch sounds
    // like a brief vowel sustain instead of a hard cut. After 8 frames
    // we still fall to comfort noise (which is then accompanied by the
    // connectionLossBeep so the user knows we're reconnecting).
    private let maxConcealmentPackets = 8
    // 🔧 1.0.21 (Option B — better PLC): pitch-cycle repetition replaces
    // the previous per-sample-faded straight repeat.
    //
    // Why this matters: a 20 ms slice of speech contains 2-4 pitch cycles
    // (average pitch ~120 Hz → 8.3 ms period). Repeating the slice
    // non-pitch-aligned produces a phase discontinuity at every packet
    // boundary that the ear hears as a metallic click / pumping. Tiling
    // ONE pitch period preserves the fundamental + harmonics so the
    // listener perceives a brief vowel sustain rather than an artifact.
    //
    // Algorithm per loss:
    //   1. Estimate pitch period via normalised autocorrelation over the
    //      last ~8 ms of the most recent good packet. Refreshed once per
    //      received packet (cheap insurance — ~10 µs per refresh).
    //   2. If voiced (correlation > 0.4), tile the pitch period to fill
    //      the missing 20 ms slot with a gentle 1.0→0.6 amplitude envelope.
    //   3. If unvoiced or no good pitch lock, fall back to the legacy
    //      per-sample fade (still better than silence).
    //   4. After `maxConcealmentPackets` consecutive losses, fade to
    //      comfort noise.
    //
    // First-loss gain is now 1.0 (was 0.5) because pitch-tiling already
    // has continuity built in — no need to attenuate to mask phase
    // mismatch we no longer produce.
    // 🔧 1.0.21 b52: matches new maxConcealmentPackets=8. Smoother decay so
    // a 160ms blip rides on a gently decaying pitch repeat instead of
    // dropping to silence at frame 3. The last value (0.05) is intentionally
    // very low so that when comfort noise takes over at frame 9 the
    // transition is barely audible.
    private let fadeSchedule: [Float] = [1.0, 0.9, 0.78, 0.65, 0.5, 0.35, 0.2, 0.08]
    private var cachedPitchPeriod: Int = 0

    /// Process a packet - returns concealed audio if packet is nil
    func process(packet: Data?, sampleRate: Double = 48000) -> Data {
        if let packet = packet {
            // Good packet - store for potential concealment + refresh pitch lock.
            lastGoodPacket = packet
            let samples = dataToFloatSamples(packet)
            lastGoodSamples = samples
            if samples.count >= 384 {
                cachedPitchPeriod = estimatePitchPeriod(samples)
            } else {
                cachedPitchPeriod = 0
            }
            consecutiveLosses = 0
            return packet
        }

        // Packet lost - attempt concealment
        consecutiveLosses += 1

        if consecutiveLosses <= maxConcealmentPackets, let lastSamples = lastGoodSamples {
            let fadeIndex = min(consecutiveLosses - 1, fadeSchedule.count - 1)
            let gain = fadeSchedule[fadeIndex]
            let n = lastSamples.count
            // Prefer pitch-tile when we have a voiced lock.
            if cachedPitchPeriod > 0, lastSamples.count >= cachedPitchPeriod {
                let concealed = pitchTileRepeat(source: lastSamples,
                                                period: cachedPitchPeriod,
                                                length: n,
                                                gain: gain)
                return floatSamplesToData(concealed)
            }
            // Unvoiced (fricative/silence) — straight per-sample fade.
            var concealedSamples = [Float](repeating: 0, count: n)
            if n > 0 {
                let invDen = 1.0 / Float(max(1, n - 1))
                for i in 0..<n {
                    let g = gain * (1.0 - Float(i) * invDen)
                    concealedSamples[i] = lastSamples[i] * g
                }
            }
            return floatSamplesToData(concealedSamples)
        }

        // Too many consecutive losses - return comfort noise
        return generateComfortNoise(samples: Int(sampleRate * 0.02))  // 20ms
    }

    /// Normalised autocorrelation pitch estimator. Searches the last ~8 ms
    /// of the buffer for the period (32–256 samples at 48 kHz → 187–1500 Hz)
    /// that produces the strongest lag-1 self-similarity. Returns 0 if no
    /// strong voiced lock — caller then uses the unvoiced fallback path.
    private func estimatePitchPeriod(_ samples: [Float]) -> Int {
        // __PITCH_PLC_RANGE_2026_09_23__ Lags 2-15 ms (96-720 samples @ 48 kHz, 500-67 Hz)
        // over the last 5 ms. Was 32-256 (187-1500 Hz) over 8 ms: a male voice (100-130 Hz,
        // period 370-480) never locked, or locked on a partial period and tiled a buzz.
        // The SHORTEST lag within 10 % of the best local maximum wins (no period doubling).
        // MEASURED (audio lab, 4 `say` voices FR/EN, this concealer modelled offline):
        // PESQ-WB mean at 3 % random loss 2.93 → 3.49 (raw PCM), 2.51 → 2.90 (0x18);
        // at 5 %: 2.27 → 2.91 and 2.11 → 2.70. Android AudioJitterBuffer uses the same rule.
        let n = samples.count
        let win = 240, minP = 96
        let maxP = min(720, n - win)
        guard maxP > minP else { return 0 }
        var energy: Float = 0
        for i in (n - win)..<n { energy += samples[i] * samples[i] }
        guard energy > Float(win) * 8.4e-7 else { return 0 }   // < ~−61 dBFS rms
        var scores = [Float](repeating: 0, count: maxP + 2)
        var best: Float = 0
        for p in minP...maxP {
            var num: Float = 0, den: Float = 0
            for i in (n - win)..<n {
                let b = samples[i - p]
                num += samples[i] * b
                den += b * b
            }
            let denom = sqrt(den * energy)
            let score = denom > 1e-10 ? num / denom : 0
            scores[p] = score
            if score > best { best = score }
        }
        guard best > 0.5 else { return 0 }
        for p in minP...maxP {
            let prev = p > minP ? scores[p - 1] : -1
            let next = p < maxP ? scores[p + 1] : -1
            if scores[p] >= 0.9 * best && scores[p] >= prev && scores[p] >= next { return p }
        }
        return 0
    }

    /// Tile one pitch period across the target length with a gentle in-frame
    /// fade (1.0 → 0.6 × `gain`) so a held vowel doesn't sustain at constant
    /// amplitude.
    private func pitchTileRepeat(source: [Float], period: Int, length: Int, gain: Float) -> [Float] {
        var out = [Float](repeating: 0, count: length)
        guard period > 0, source.count >= period else { return out }
        let tailStart = source.count - period
        let denom = Float(max(1, length - 1))
        for i in 0..<length {
            let envelope = gain * (1.0 - 0.4 * Float(i) / denom)
            out[i] = source[tailStart + (i % period)] * envelope
        }
        return out
    }
    
    /// Generate comfort noise — digital silence.
    /// 🔧 FIX (2026-07-27): this used to fill the buffer with
    /// `Float.random(in: -0.01...0.01)`. That is flat white noise, and
    /// `playAudioData` then multiplies the concealer's output by 6.6, landing it
    /// at about −23.6 dBFS of audible hiss — a real, measurable contribution to
    /// the "noisy" symptom, injected on every extended loss burst. It was also
    /// the ODD ONE OUT: `AACELDCodec.comfortNoise` and
    /// `VoiceCallManager.playComfortNoise` both already return zeros. Three
    /// implementations of one idea, one of them wrong; they now agree. Zeros
    /// produce no audible crackling and no hiss.
    func generateComfortNoise(samples: Int) -> Data {
        return Data(count: samples * MemoryLayout<Float>.size)
    }
    
    private func dataToFloatSamples(_ data: Data) -> [Float] {
        var samples = [Float](repeating: 0, count: data.count / 4)
        _ = samples.withUnsafeMutableBytes { dest in
            data.copyBytes(to: dest)
        }
        return samples
    }
    
    private func floatSamplesToData(_ samples: [Float]) -> Data {
        return samples.withUnsafeBytes { Data($0) }
    }
    
    func reset() {
        lastGoodPacket = nil
        lastGoodSamples = nil
        consecutiveLosses = 0
        cachedPitchPeriod = 0
    }
}

// ============================================================================
// SIMPLE XOR-BASED FEC (Forward Error Correction)
// ============================================================================
// Adds redundancy to recover from single packet losses
// Every N packets, send an XOR of the previous N packets

class SimpleXORFEC {
    private let groupSize: Int  // Number of packets per FEC group
    private var currentGroup: [Data] = []
    private var groupSequenceStart: UInt64 = 0
    private var receivedGroups: [UInt64: [UInt64: Data]] = [:]  // groupStart -> (seq -> data)
    private var receivedFEC: [UInt64: Data] = [:]  // groupStart -> FEC packet
    
    init(groupSize: Int = 4) {
        self.groupSize = groupSize
    }
    
    // MARK: - Sender Side
    
    /// Add a packet for FEC encoding
    /// - Returns: FEC packet if group is complete, nil otherwise
    func addPacketForEncoding(_ packet: Data, sequenceNumber: UInt64) -> Data? {
        // Start new group if needed
        if currentGroup.isEmpty {
            groupSequenceStart = sequenceNumber
        }
        
        currentGroup.append(packet)
        
        // Check if group is complete
        if currentGroup.count == groupSize {
            let fecPacket = generateFECPacket()
            currentGroup.removeAll()
            return fecPacket
        }
        
        return nil
    }
    
    /// Generate XOR FEC packet for current group
    private func generateFECPacket() -> Data {
        guard !currentGroup.isEmpty else { return Data() }
        
        // Find max length
        let maxLength = currentGroup.map { $0.count }.max() ?? 0
        var result = [UInt8](repeating: 0, count: maxLength)
        
        // XOR all packets together
        for packet in currentGroup {
            let bytes = [UInt8](packet)
            for i in 0..<bytes.count {
                result[i] ^= bytes[i]
            }
        }
        
        // Prepend group info: [groupStart(8 bytes)][groupSize(1 byte)][XOR data]
        var fecData = Data()
        var startBE = groupSequenceStart.bigEndian  // Big-endian for cross-platform
        fecData.append(Data(bytes: &startBE, count: 8))
        fecData.append(UInt8(groupSize))
        fecData.append(Data(result))
        
        return fecData
    }
    
    // MARK: - Receiver Side
    
    /// Store received packet for potential FEC recovery
    func storeReceivedPacket(_ packet: Data, sequenceNumber: UInt64) {
        let groupStart = (sequenceNumber / UInt64(groupSize)) * UInt64(groupSize)
        
        if receivedGroups[groupStart] == nil {
            receivedGroups[groupStart] = [:]
        }
        receivedGroups[groupStart]?[sequenceNumber] = packet
        
        // Clean up old groups (keep last 10)
        cleanupOldGroups()
    }
    
    /// Process received FEC packet
    func processFECPacket(_ fecData: Data) {
        guard fecData.count > 9 else { return }

        // 🔧 FIX: Use safe unaligned byte reading to prevent crash
        var groupStart: UInt64 = 0
        let groupData = fecData.prefix(8)
        _ = Swift.withUnsafeMutableBytes(of: &groupStart) { dest in
            groupData.copyBytes(to: dest)
        }
        groupStart = UInt64(bigEndian: groupStart)
        // let size = Int(fecData[8])  // Not used currently but could validate
        let xorData = Data(fecData.suffix(from: 9))

        receivedFEC[groupStart] = xorData
    }

    // 🔧 FIX (2026-07-27): DELETED recoverDroppedFrameForGroup(parityGroupStart:).
    // It fabricated an audio frame every time a parity packet arrived and the
    // receiver's bucket looked one short — which, because the sender keys a
    // group by the first AUDIO nonce while the receiver buckets by (seq/4)*4 and
    // the parity burns a nonce of its own, happens on a fixed lcm(4,5) = 20
    // nonce beat regardless of the link: 3.0 phantom "recoveries" per second,
    // every one of them on a sequence ≡ 19 (mod 20), on a 20–27 ms RTT link with
    // ~1 % real loss (41/40/30 injections across three captured calls, zero
    // exceptions). The consequences were a phantom 6.0 % loss reading that
    // pinned the codec at its 32 kbps floor (~12 dB of segSNR) and a double
    // decode of the same AAC frame through the single stateful AAC-ELD decoder.
    // Real losses are still recovered by tryRecover() below, off the
    // decrypt-fail path — i.e. only for a frame we watched fail. See the long
    // note at the FEC_PACKET_TYPE branch in handleIncomingAudioPacket.

    /// Try to recover a lost packet using FEC
    /// - Returns: Recovered packet or nil if not possible
    func tryRecover(sequenceNumber: UInt64) -> Data? {
        let groupStart = (sequenceNumber / UInt64(groupSize)) * UInt64(groupSize)
        
        guard let groupPackets = receivedGroups[groupStart],
              let fecData = receivedFEC[groupStart] else {
            return nil
        }
        
        // Check if we have exactly groupSize - 1 packets (missing just one)
        let expectedSeqs = (0..<groupSize).map { groupStart + UInt64($0) }
        let missingSeqs = expectedSeqs.filter { groupPackets[$0] == nil }
        
        guard missingSeqs.count == 1, missingSeqs.first == sequenceNumber else {
            return nil  // Can't recover if more than one packet missing
        }
        
        // Recover by XORing FEC with all other packets
        var result = [UInt8](fecData)
        
        for seq in expectedSeqs where seq != sequenceNumber {
            if let packet = groupPackets[seq] {
                let bytes = [UInt8](packet)
                for i in 0..<min(bytes.count, result.count) {
                    result[i] ^= bytes[i]
                }
            }
        }
        
        OshiLog.call.info("🔧 FEC: Recovered packet #\(sequenceNumber) from group \(groupStart)")
        return Data(result)
    }
    
    private func cleanupOldGroups() {
        // Keep only last 10 groups
        let sortedStarts = receivedGroups.keys.sorted()
        if sortedStarts.count > 10 {
            let toRemove = sortedStarts.prefix(sortedStarts.count - 10)
            for start in toRemove {
                 receivedFEC.removeValue(forKey: start)
            }
        }
    }
    
    func reset() {
        currentGroup.removeAll()
        receivedGroups.removeAll()
        receivedFEC.removeAll()
        groupSequenceStart = 0
    }
}

// ============================================================================
// AUDIO CODEC WRAPPER (Preparation for Opus)
// ============================================================================
// Abstract interface for audio compression
// Currently uses PCM, but can be swapped for Opus when library is added

protocol AudioCodec {
    func encode(_ pcmData: Data) -> Data
    func decode(_ encodedData: Data) -> Data
    var compressionRatio: Double { get }
    var name: String { get }
    func setBitrate(_ bitrate: Int32)
    func setExpectedPacketLoss(_ percent: Int32)
    func reset()

    // MARK: Frame-size contract (see DIAG_FRAME_CONTRACT)
    //
    // 🔧 FIX (2026-07-27): the whole receive pipeline — the jitter buffer's
    // 20 ms slot cadence, `audioPlayerPacketMs`, the PLC/comfort-noise frame
    // size and the FEC group geometry — assumes that ONE wire packet carries
    // exactly ONE mic frame's worth of audio (960 frames = 20 ms @ 48 kHz).
    // A codec whose native packet is shorter than that MUST pack several of
    // its own packets into one wire packet, otherwise the receiver is handed
    // less audio than real time and AVAudioPlayerNode runs dry every slot.
    // These two numbers exist so that assumption is checkable instead of
    // implicit — see `emitDiagFrameContract()`.

    /// Frames of 48 kHz PCM in ONE of the codec's own packets. 0 = the codec
    /// has no fixed packet size (pass-through).
    var codecFramesPerPacket: Int { get }
    /// Frames of 48 kHz PCM the codec puts into ONE wire packet, i.e. into the
    /// Data returned by a single `encode()` call fed one mic frame. Must equal
    /// the pipeline's frames-per-packet. 0 = pass-through.
    var framesPerWirePacket: Int { get }
}

/// PCM "codec" - no compression (fallback)
class PCMCodec: AudioCodec {
    func encode(_ pcmData: Data) -> Data { pcmData }
    func decode(_ encodedData: Data) -> Data { encodedData }
    var compressionRatio: Double { 1.0 }
    func setBitrate(_ bitrate: Int32) {}
    func setExpectedPacketLoss(_ percent: Int32) {}
    func reset() {}
    var name: String { "PCM (Uncompressed)" }
    // Pass-through: whatever it is handed comes back out, so it can never
    // violate the frame contract.
    var codecFramesPerPacket: Int { 0 }
    var framesPerWirePacket: Int { 0 }
}

// MARK: - AAC-ELD Codec (Crystal Clear VoIP Audio)
// Apple's built-in AudioToolbox — same codec as FaceTime
// 48kHz mono, 24-80kbps adaptive, ~15ms codec delay
// Comparable to Opus (used by WhatsApp/Telegram) on iOS

/// Encode callback context — stores pointer to PCM input for AudioConverter
private struct AACEncodeContext {
    var inputData: UnsafeRawPointer
    var inputByteSize: UInt32
    var frameCount: UInt32
    var consumed: Bool
}

/// Decode callback context — stores pointer to AAC input + packet description
private struct AACDecodeContext {
    var inputData: UnsafeRawPointer
    var inputByteSize: UInt32
    var packetDescPtr: UnsafeMutablePointer<AudioStreamPacketDescription>
    var consumed: Bool
}

/// AAC-ELD Encode input callback (C-compatible)
private let aacEncodeInputCallback: AudioConverterComplexInputDataProc = {
    (_, ioNumberDataPackets, ioData, _, inUserData) -> OSStatus in
    guard let ctx = inUserData?.assumingMemoryBound(to: AACEncodeContext.self) else {
        ioNumberDataPackets.pointee = 0; return -50 // paramErr
    }
    if ctx.pointee.consumed {
        ioNumberDataPackets.pointee = 0; return -1 // no more data
    }
    ioNumberDataPackets.pointee = ctx.pointee.frameCount
    ioData.pointee.mNumberBuffers = 1
    ioData.pointee.mBuffers.mNumberChannels = 1
    ioData.pointee.mBuffers.mDataByteSize = ctx.pointee.inputByteSize
    ioData.pointee.mBuffers.mData = UnsafeMutableRawPointer(mutating: ctx.pointee.inputData)
    ctx.pointee.consumed = true
    return noErr
}

/// AAC-ELD Decode input callback (C-compatible)
private let aacDecodeInputCallback: AudioConverterComplexInputDataProc = {
    (_, ioNumberDataPackets, ioData, outDataPacketDescription, inUserData) -> OSStatus in
    guard let ctx = inUserData?.assumingMemoryBound(to: AACDecodeContext.self) else {
        ioNumberDataPackets.pointee = 0; return -50 // paramErr
    }
    if ctx.pointee.consumed {
        ioNumberDataPackets.pointee = 0; return -1 // no more data
    }
    ioNumberDataPackets.pointee = 1 // 1 AAC packet
    ioData.pointee.mNumberBuffers = 1
    ioData.pointee.mBuffers.mNumberChannels = 1
    ioData.pointee.mBuffers.mDataByteSize = ctx.pointee.inputByteSize
    ioData.pointee.mBuffers.mData = UnsafeMutableRawPointer(mutating: ctx.pointee.inputData)
    // Provide packet description — tells AudioConverter where the AAC packet is
    if let outDesc = outDataPacketDescription {
        outDesc.pointee = ctx.pointee.packetDescPtr
    }
    ctx.pointee.consumed = true
    return noErr
}

class AACELDCodec: AudioCodec {
    private var encoder: AudioConverterRef?
    private var decoder: AudioConverterRef?
    private var isValid = false
    private var framesPerPacket: UInt32 = 480  // Actual frames per AAC-ELD packet (queried from converter)
    private var consecutiveSilentFrames: Int = 0
    private let silenceThreshold: Int16 = 30   // Very low — iPad mic peaks at ~235 for voice, ~15 ambient
    private let maxSilentFrames: Int = 100     // ~2s of true silence before DTX — never cut voice
    private var encodeOutputBuffer = [UInt8](repeating: 0, count: 4096) // Pre-allocated, no COW
    private var encodeFailCount: Int = 0
    private var decodeFailCount: Int = 0
    private var encodeCallCount: Int = 0
    private let encodeLock = NSLock() // Protects encoder + encodeCarry (real-time audio thread)
    private let decodeLock = NSLock() // Protects decoder only (WS processing thread)

    // 🔧 FIX (2026-07-27) — frame-size contract, see DIAG_FRAME_CONTRACT.
    //
    // AAC-ELD's native packet at 48 kHz is 512 frames (10.67 ms), NOT 960
    // (20 ms). The mic tap hands us 960 frames per call. The old loop was:
    //
    //     while done < totalFrames {
    //         let todo = min(fpp, totalFrames - done)
    //         if todo < fpp { break }        // ← discards the 448-frame tail
    //         ...
    //     }
    //
    // so every single 20 ms mic frame was encoded as ONE 512-frame packet and
    // the remaining 448 frames (46.7 % of the microphone) were thrown away
    // with no log line. MEASURED on device (2026-07-27 14:04 call, f14):
    // `🎙️ ENC #N samples:960` + `Actual framesPerPacket=512` + the receiver's
    // `DIAG_AUDIO_RX_PCM | samples=512` and `DIAG_PLAYBACK_RATE | playerQueueMs=0`
    // — the player node was chronically dry because it consumes 93.75
    // buffers/s of 512 frames but was only ever handed ~50–64/s.
    //
    // A standalone AudioToolbox harness confirmed the two halves of this:
    //   960-in / fpp 512 / tail dropped → 53 % of real time delivered
    //   960-in + carry-over            → 100 % of real time, output RMS 1821
    //                                    vs source 1828 (i.e. the codec itself
    //                                    is fine; only the framing was wrong)
    //
    // Fix: carry the sub-packet remainder across calls so every whole 512-frame
    // block is encoded exactly once, in order, with no gaps. One `encode()` of
    // a 960-frame mic buffer now emits 1 or 2 length-prefixed AAC packets
    // (1.875 on average) — `decode()` already loops over a length-prefixed
    // packet list, and `emitDiagCodec`'s own byte arithmetic has always
    // documented "two per 20 ms", so the rest of the stack already expected
    // this. Carry never exceeds fpp-1 frames (≤10.6 ms), so this adds no
    // steady-state latency.
    private var encodeCarry: [Int16] = []

    /// Kill switch. `true` restores the pre-fix behaviour (encode the first
    /// 512 frames of each mic buffer, drop the rest). Default is FALSE — the
    /// reframe is ON — because the old path is measured to discard 46.7 % of
    /// the microphone and starve the player node, i.e. leaving it on by
    /// default would knowingly ship a dead call. Set
    /// `OSHIAudioDisableEncoderReframe = YES` in UserDefaults to revert.
    private let reframeDisabled: Bool = UserDefaults.standard.bool(forKey: "OSHIAudioDisableEncoderReframe")

    /// 512 @ 48 kHz for AAC-ELD (queried from the converter, see setupEncoder).
    var codecFramesPerPacket: Int { Int(framesPerPacket) }

    /// One `encode()` call consumes one 20 ms mic frame and emits every whole
    /// codec packet that the accumulated PCM allows — so a wire packet carries
    /// 960 frames of audio on average, matching the pipeline. With the reframe
    /// disabled it carries only `framesPerPacket`, which DIAG_FRAME_CONTRACT
    /// will then flag as a MISMATCH.
    var framesPerWirePacket: Int { reframeDisabled ? Int(framesPerPacket) : 960 }

    init() {
        setupEncoder()
        setupDecoder()
        if encoder != nil && decoder != nil {
            isValid = true
            fileLog.log("🎵 AACELDCodec: Initialized — 48kHz mono, \(framesPerPacket) frames/codec-pkt, \(framesPerWirePacket) frames/wire-pkt, reframe=\(reframeDisabled ? "OFF" : "ON")")
        } else {
            fileLog.log("⚠️ AACELDCodec: Init FAILED — using ADPCM fallback")
        }
    }

    private func setupEncoder() {
        var inASBD = AudioStreamBasicDescription(
            mSampleRate: 48000, mFormatID: kAudioFormatLinearPCM,
            mFormatFlags: kAudioFormatFlagIsSignedInteger | kAudioFormatFlagIsPacked,
            mBytesPerPacket: 2, mFramesPerPacket: 1, mBytesPerFrame: 2,
            mChannelsPerFrame: 1, mBitsPerChannel: 16, mReserved: 0)
        var outASBD = AudioStreamBasicDescription(
            mSampleRate: 48000, mFormatID: kAudioFormatMPEG4AAC_ELD,
            mFormatFlags: 0, mBytesPerPacket: 0, mFramesPerPacket: 0, // Let system fill in
            mBytesPerFrame: 0, mChannelsPerFrame: 1, mBitsPerChannel: 0, mReserved: 0)
        var enc: AudioConverterRef?
        let status = AudioConverterNew(&inASBD, &outASBD, &enc)
        guard status == noErr, let c = enc else {
            fileLog.log("❌ AACELDCodec encoder create failed: OSStatus \(status)"); return
        }
        // Set bitrate
        var br: UInt32 = 64000
        AudioConverterSetProperty(c, kAudioConverterEncodeBitRate,
                                  UInt32(MemoryLayout<UInt32>.size), &br)
        // Query actual output ASBD to get real framesPerPacket
        var actualASBD = AudioStreamBasicDescription()
        var asbdSize = UInt32(MemoryLayout<AudioStreamBasicDescription>.size)
        let queryStatus = AudioConverterGetProperty(c, kAudioConverterCurrentOutputStreamDescription,
                                                     &asbdSize, &actualASBD)
        if queryStatus == noErr && actualASBD.mFramesPerPacket > 0 {
            framesPerPacket = actualASBD.mFramesPerPacket
            fileLog.log("🎵 AACELDCodec: Actual framesPerPacket=\(framesPerPacket)")
        } else {
            framesPerPacket = 480 // Safe default for AAC-ELD at 48kHz
        }
        encoder = c
    }

    private func setupDecoder() {
        var inASBD = AudioStreamBasicDescription(
            mSampleRate: 48000, mFormatID: kAudioFormatMPEG4AAC_ELD,
            mFormatFlags: 0, mBytesPerPacket: 0, mFramesPerPacket: framesPerPacket,
            mBytesPerFrame: 0, mChannelsPerFrame: 1, mBitsPerChannel: 0, mReserved: 0)
        var outASBD = AudioStreamBasicDescription(
            mSampleRate: 48000, mFormatID: kAudioFormatLinearPCM,
            mFormatFlags: kAudioFormatFlagIsSignedInteger | kAudioFormatFlagIsPacked,
            mBytesPerPacket: 2, mFramesPerPacket: 1, mBytesPerFrame: 2,
            mChannelsPerFrame: 1, mBitsPerChannel: 16, mReserved: 0)
        var dec: AudioConverterRef?
        let status = AudioConverterNew(&inASBD, &outASBD, &dec)
        guard status == noErr, let c = dec else {
            fileLog.log("❌ AACELDCodec decoder create failed: OSStatus \(status)"); return
        }
        decoder = c
    }

    func encode(_ pcmData: Data) -> Data {
        guard isValid, let enc = encoder else { return adpcmFallbackEncode(pcmData) }
        let sampleCount = pcmData.count / 2
        guard sampleCount > 0 else { return Data([0xFF]) }

        // DTX: silence detection — save bandwidth by sending marker byte
        var maxAmp: Int16 = 0
        pcmData.withUnsafeBytes { raw in
            let s = raw.bindMemory(to: Int16.self)
            for i in 0..<min(sampleCount, s.count) {
                let a = abs(s[i]); if a > maxAmp { maxAmp = a }
            }
        }
        // Log audio levels for first 20 buffers + every 100th to diagnose mic issues
        encodeCallCount += 1
        if encodeCallCount <= 20 || encodeCallCount % 100 == 0 {
            fileLog.log("🎙️ ENC #\(encodeCallCount) samples:\(sampleCount) maxAmp:\(maxAmp) silent:\(consecutiveSilentFrames)")
        }
        if maxAmp < silenceThreshold {
            consecutiveSilentFrames += 1
            if consecutiveSilentFrames > maxSilentFrames {
                // Declared silence — drop any partial block so we never stitch a
                // stale fragment onto the first frame of resumed speech.
                encodeLock.lock(); encodeCarry.removeAll(keepingCapacity: true); encodeLock.unlock()
                return Data([0xFF])
            }
        } else { consecutiveSilentFrames = 0 }

        encodeLock.lock()
        defer { encodeLock.unlock() }

        var result = Data()
        let fpp = framesPerPacket

        if reframeDisabled {
            // Legacy path (kill switch): encode only the first whole codec packet
            // of this mic buffer and discard the remainder. Kept verbatim so the
            // UserDefaults revert is a true revert.
            let totalFrames = UInt32(sampleCount)
            var done: UInt32 = 0
            pcmData.withUnsafeBytes { rawIn in
                guard let base = rawIn.baseAddress else { return }
                while done < totalFrames {
                    let todo = min(fpp, totalFrames - done)
                    if todo < fpp { break } // Don't encode partial frames
                    encodeBlock(enc, base.advanced(by: Int(done) * 2), frames: todo, into: &result)
                    done += todo
                }
            }
            return result.isEmpty ? Data([0xFF]) : result
        }

        // Reframe path: append this mic buffer to the carry, then emit EVERY
        // whole codec packet the accumulated PCM allows. Nothing is discarded,
        // the samples stay contiguous across calls, and the leftover (< fpp
        // frames) waits for the next mic buffer.
        //
        // Read the Int16 samples byte-wise — `pcmData` comes from
        // `float32ToInt16`, which builds it by appending, so its base address
        // carries no alignment guarantee (this is the same hazard that broke
        // int16ToFloat32; `int16PcmStats` reads byte-wise for the same reason).
        let carryBefore = encodeCarry.count
        encodeCarry.reserveCapacity(carryBefore + sampleCount)
        pcmData.withUnsafeBytes { rb in
            guard let b = rb.baseAddress?.assumingMemoryBound(to: UInt8.self) else { return }
            for i in 0..<sampleCount {
                let lo = UInt16(b[i * 2])
                let hi = UInt16(b[i * 2 + 1])
                encodeCarry.append(Int16(bitPattern: (hi << 8) | lo))
            }
        }

        let blockFrames = Int(fpp)
        let wholeBlocks = blockFrames > 0 ? encodeCarry.count / blockFrames : 0
        if wholeBlocks > 0 {
            encodeCarry.withUnsafeBufferPointer { buf in
                guard let base = buf.baseAddress else { return }
                for blk in 0..<wholeBlocks {
                    encodeBlock(enc,
                                UnsafeRawPointer(base.advanced(by: blk * blockFrames)),
                                frames: fpp,
                                into: &result)
                }
            }
            encodeCarry.removeFirst(wholeBlocks * blockFrames)
        }

        return result.isEmpty ? Data([0xFF]) : result
    }

    /// Encode ONE whole codec packet (`frames` == framesPerPacket) from `base`
    /// and append it to `result` as [len:UInt16 LE][aac bytes]. Caller holds
    /// `encodeLock`. Extracted so the reframe path and the legacy kill-switch
    /// path can never drift apart.
    private func encodeBlock(_ enc: AudioConverterRef,
                             _ base: UnsafeRawPointer,
                             frames: UInt32,
                             into result: inout Data) {
        var ctx = AACEncodeContext(
            inputData: base,
            inputByteSize: frames * 2,
            frameCount: frames,
            consumed: false)
        var outPktCount: UInt32 = 1
        var outBufList = AudioBufferList(
            mNumberBuffers: 1,
            mBuffers: AudioBuffer(
                mNumberChannels: 1,
                mDataByteSize: UInt32(encodeOutputBuffer.count),
                mData: nil))

        encodeOutputBuffer.withUnsafeMutableBufferPointer { outBuf in
            guard let baseAddr = outBuf.baseAddress else { return }
            outBufList.mBuffers.mData = UnsafeMutableRawPointer(baseAddr)
            outBufList.mBuffers.mDataByteSize = UInt32(outBuf.count)
            var pd = AudioStreamPacketDescription()

            let st = withUnsafeMutablePointer(to: &ctx) { ctxPtr in
                AudioConverterFillComplexBuffer(
                    enc, aacEncodeInputCallback, ctxPtr,
                    &outPktCount, &outBufList, &pd)
            }
            // Status -1 is normal: callback returns -1 when input is consumed
            if (st == noErr || st == -1) && outPktCount > 0 {
                let n = Int(outBufList.mBuffers.mDataByteSize)
                if n > 0 && n < outBuf.count {
                    var len = UInt16(n).littleEndian
                    result.append(Data(bytes: &len, count: 2))
                    result.append(Data(bytesNoCopy: baseAddr,
                                       count: n, deallocator: .none))
                }
            } else if st != noErr && st != -1 {
                encodeFailCount += 1
                if encodeFailCount <= 5 {
                    fileLog.log("❌ AACELDCodec encode err: \(st) (fail #\(encodeFailCount))")
                }
            }
        }
    }

    func decode(_ encodedData: Data) -> Data {
        if encodedData.count == 1 && encodedData[0] == 0xFF {
            // One pipeline frame (960 @ 48 kHz = 20 ms) of true silence, so a DTX
            // packet occupies exactly the slot the jitter buffer reserved for it.
            return comfortNoise(framesPerWirePacket)
        }
        guard isValid, let dec = decoder else { return adpcmFallbackDecode(encodedData) }

        decodeLock.lock()
        defer { decodeLock.unlock() }

        var result = Data()
        var off = 0
        let outFrames = framesPerPacket
        let outByteSize = outFrames * 2 // Int16 samples

        while off + 2 <= encodedData.count {
            // Read 2-byte little-endian packet length
            let pLen: Int
            if off + 1 < encodedData.count {
                pLen = Int(encodedData[off]) | (Int(encodedData[off + 1]) << 8)
            } else { break }
            off += 2
            guard pLen > 0 && pLen < 4096 && off + pLen <= encodedData.count else { break }

            // Copy AAC packet to contiguous buffer for safe pointer access
            let aacPacket = [UInt8](encodedData[off..<(off + pLen)])
            off += pLen

            // Allocate output buffer for decoded PCM
            var outSamples = [UInt8](repeating: 0, count: Int(outByteSize))

            // Packet description — lives on stack, pointer is valid for duration of scope
            var packetDesc = AudioStreamPacketDescription(
                mStartOffset: 0,
                mVariableFramesInPacket: 0,
                mDataByteSize: UInt32(pLen))

            aacPacket.withUnsafeBufferPointer { aacBuf in
                guard let aacPtr = aacBuf.baseAddress else { return }

                withUnsafeMutablePointer(to: &packetDesc) { pdPtr in
                    var ctx = AACDecodeContext(
                        inputData: UnsafeRawPointer(aacPtr),
                        inputByteSize: UInt32(pLen),
                        packetDescPtr: pdPtr,
                        consumed: false)

                    var outBufList = AudioBufferList(
                        mNumberBuffers: 1,
                        mBuffers: AudioBuffer(
                            mNumberChannels: 1,
                            mDataByteSize: outByteSize,
                            mData: nil))
                    var outPktCount = outFrames

                    outSamples.withUnsafeMutableBufferPointer { outBuf in
                        guard let baseAddr = outBuf.baseAddress else { return }
                        outBufList.mBuffers.mData = UnsafeMutableRawPointer(baseAddr)
                        outBufList.mBuffers.mDataByteSize = outByteSize

                        let st = withUnsafeMutablePointer(to: &ctx) { ctxPtr in
                            AudioConverterFillComplexBuffer(
                                dec, aacDecodeInputCallback, ctxPtr,
                                &outPktCount, &outBufList, nil)
                        }
                        // Status -1 is normal: callback returns -1 when input consumed
                        // 🔧 FIX (2026-07-27): require the FULL frame, not just
                        // "> 0 bytes". A partial decode is not audio — one capture
                        // shows `samples=20 peak=32767 rms=21980`, i.e. a
                        // sub-millisecond FULL-SCALE click, appended to the playout
                        // stream immediately after a FEC injection. AAC-ELD emits
                        // exactly `framesPerPacket` samples or it has failed; a short
                        // buffer is decoder garbage and must be dropped, letting the
                        // caller fall through to comfort noise (silence).
                        if (st == noErr || st == -1) && outBufList.mBuffers.mDataByteSize == outByteSize {
                            let decoded = Int(outBufList.mBuffers.mDataByteSize)
                            result.append(Data(bytesNoCopy: baseAddr,
                                               count: decoded, deallocator: .none))
                        } else if st != noErr && st != -1 {
                            decodeFailCount += 1
                            if decodeFailCount <= 5 {
                                fileLog.log("❌ AACELDCodec decode err: \(st) pLen:\(pLen) (fail #\(decodeFailCount))")
                            }
                        }
                    }
                }
            }
        }
        return result.isEmpty ? comfortNoise(framesPerWirePacket) : result
    }

    private func comfortNoise(_ samples: Int) -> Data {
        // True silence — zeros produce no audible noise/crackling
        return Data(count: samples * 2)
    }

    // MARK: - ADPCM Fallback (if AAC-ELD unavailable on device)
    private var fbEnc = G726FallbackState(); private var fbDec = G726FallbackState()
    private var fbPre: Int32 = 0; private var fbDe: Int32 = 0; private let fbC: Int32 = 27853

    private func adpcmFallbackEncode(_ pcmData: Data) -> Data {
        var s = [Int16](); s.reserveCapacity(pcmData.count / 2)
        for i in stride(from: 0, to: pcmData.count - 1, by: 2) {
            s.append(Int16(pcmData[i]) | (Int16(pcmData[i+1]) << 8))
        }
        var e = [Int16](); e.reserveCapacity(s.count)
        for v in s { let x = Int32(v) - ((fbC * fbPre) >> 15); fbPre = Int32(v); e.append(Int16(clamping: x)) }
        var r = Data(); var buf: UInt8 = 0; var cnt = 0
        for v in e {
            let n = fbEnc.encode(sample: v)
            if cnt == 0 { buf = n & 0x0F; cnt = 1 } else { buf |= (n & 0x0F) << 4; r.append(buf); cnt = 0 }
        }
        if cnt == 1 { r.append(buf) }; return r
    }

    private func adpcmFallbackDecode(_ data: Data) -> Data {
        if data.count == 1 && data[0] == 0xFF { return comfortNoise(framesPerWirePacket) }
        var s = [Int16](); s.reserveCapacity(data.count * 2)
        for b in data { s.append(fbDec.decode(adpcm: b & 0x0F)); s.append(fbDec.decode(adpcm: (b >> 4) & 0x0F)) }
        for i in 0..<s.count {
            let d = Int32(s[i]) + ((fbC * fbDe) >> 15); let c = max(-32768, min(32767, d)); fbDe = c; s[i] = Int16(c)
        }
        var r = Data(capacity: s.count * 2)
        for v in s { var x = v; r.append(Data(bytes: &x, count: 2)) }; return r
    }

    var compressionRatio: Double { 12.0 }
    var name: String { isValid ? "AAC-ELD (\(framesPerPacket)fpp @ 48kHz)" : "G.726 ADPCM fallback" }

    func setBitrate(_ bitrate: Int32) {
        guard let enc = encoder else { return }
        encodeLock.lock()
        var br = UInt32(bitrate)
        AudioConverterSetProperty(enc, kAudioConverterEncodeBitRate,
                                  UInt32(MemoryLayout<UInt32>.size), &br)
        encodeLock.unlock()
        fileLog.log("🎵 AACELDCodec: setBitrate \(bitrate/1000)kbps")
    }

    func setExpectedPacketLoss(_ percent: Int32) {}

    func reset() {
        encodeLock.lock()
        if let e = encoder { AudioConverterReset(e) }
        consecutiveSilentFrames = 0; encodeFailCount = 0; encodeCallCount = 0
        encodeCarry.removeAll(keepingCapacity: true)
        encodeLock.unlock()
        decodeLock.lock()
        if let d = decoder { AudioConverterReset(d) }
        decodeFailCount = 0
        decodeLock.unlock()
        fbPre = 0; fbDe = 0; fbEnc.reset(); fbDec.reset()
    }

    deinit {
        if let e = encoder { AudioConverterDispose(e) }
        if let d = decoder { AudioConverterDispose(d) }
    }
}

/// G.726 ADPCM state for fallback (if AAC-ELD unavailable)
private class G726FallbackState {
    private var stepIndex: Int = 0; private var predicted: Int32 = 0
    private let steps: [Int32] = [
        16,17,19,21,23,25,28,31,34,37,41,45,50,55,60,66,73,80,88,97,107,118,130,143,157,173,190,209,
        230,253,279,307,337,371,408,449,494,544,598,658,724,796,876,963,1060,1166,1282,1411,1552,1707,
        1878,2066,2272,2499,2749,3024,3327,3660,4026,4428,4871,5358,5894,6484,7132,7845,8630,9493,
        10442,11487,12635,13899,15289,16818,18500,20350,22385,24623,27086,29794,32767]
    private let idx: [Int] = [-1,-1,-1,-1,2,4,6,8,-1,-1,-1,-1,2,4,6,8]
    func encode(sample: Int16) -> UInt8 {
        let s = steps[stepIndex]; var d = Int32(sample) - predicted; var c: UInt8 = 0
        if d < 0 { c = 8; d = -d }
        var m: UInt8 = 4; var t = s
        for _ in stride(from: 2, through: 0, by: -1) { if d >= t { c |= m; d -= t }; t >>= 1; m >>= 1 }
        upd(c, s); stepIndex = max(0, min(stepIndex + idx[Int(c)], steps.count - 1)); return c
    }
    func decode(adpcm: UInt8) -> Int16 {
        let s = steps[stepIndex]; upd(adpcm, s)
        stepIndex = max(0, min(stepIndex + idx[Int(adpcm & 0x0F)], steps.count - 1))
        return Int16(clamping: max(-32768, min(32767, predicted)))
    }
    private func upd(_ c: UInt8, _ s: Int32) {
        var d: Int32 = s >> 3
        if c & 4 != 0 { d += s }; if c & 2 != 0 { d += s >> 1 }; if c & 1 != 0 { d += s >> 2 }
        predicted += (c & 8 != 0) ? -d : d; predicted = max(-32768, min(32767, predicted))
    }
    func reset() { stepIndex = 0; predicted = 0 }
}


// MARK: - Call State
enum CallState: Equatable {
    case idle
    case connecting
    case ringing
    case inCall
    case ended(reason: CallEndReason)
    
    static func == (lhs: CallState, rhs: CallState) -> Bool {
        switch (lhs, rhs) {
        case (.idle, .idle), (.connecting, .connecting), (.ringing, .ringing), (.inCall, .inCall):
            return true
        case (.ended(let r1), .ended(let r2)):
            return r1 == r2
        default:
            return false
        }
    }
}

extension CallState: CustomStringConvertible {
    var description: String {
        switch self {
        case .idle: return "idle"
        case .connecting: return "connecting"
        case .ringing: return "ringing"
        case .inCall: return "inCall"
        case .ended(let reason): return "ended(\(reason.rawValue))"
        }
    }
}

enum CallEndReason: String {
    case hungUp = "hung_up"
    case declined = "declined"
    case noAnswer = "no_answer"
    case networkError = "network_error"
    case peerDisconnected = "peer_disconnected"
    case connectionLost = "connection_lost"  // 📶 NEW: Auto-ended due to 30s silence
    case answeredElsewhere = "answered_elsewhere"  // 📱 Multi-device: Call answered on another device

    /// User-friendly display text for call end reason
    var displayText: String {
        switch self {
        case .hungUp: return "Call ended"
        case .declined: return "Call declined"
        case .noAnswer: return "No answer"
        case .networkError: return "Network error"
        case .peerDisconnected: return "Connection lost"
        case .connectionLost: return "Connection lost"
        case .answeredElsewhere: return "Answered on another device"
        }
    }
}

// MARK: - Voice Effect for Calls (Real-time)
enum CallVoiceEffect: String, CaseIterable, Identifiable {
    case none = "None"
    case robot = "Robot"
    case alien = "Alien"
    case deep = "Deep"
    case chipmunk = "Chipmunk"
    case echo = "Echo"
    case reverb = "Reverb"
    case anonymous = "Anonymous"  // Special effect for maximum privacy

    var id: String { rawValue }

    /// 🌍 __EFFECT_NAMES_WERE_ENGLISH_2026_08_20__ This returned `rawValue`, so a
    /// French user picking a voice effect read "Chipmunk" and "Anonymous" in an app
    /// that ships 34 languages. The raw value is the WIRE/storage identity and must
    /// not change; only what the human reads does.
    ///
    /// `.none` reuses `common.off`, which already exists 34/34 — "no effect" is the
    /// same idea the rest of the app already spells that way, and inventing a 35th
    /// string for it would be a translation to maintain for nothing.
    var displayName: String {
        switch self {
        case .none: return "common.off".localized
        default:    return "call.voice_effect.\(rawValue.lowercased())".localized
        }
    }

    var icon: String {
        switch self {
        case .none: return "waveform"
        case .robot: return "cpu"
        case .alien: return "antenna.radiowaves.left.and.right"
        case .deep: return "waveform"
        case .chipmunk: return "hare"
        case .echo: return "dot.radiowaves.left.and.right"
        case .reverb: return "building.columns"
        case .anonymous: return "person.fill.questionmark"
        }
    }

    var description: String {
        switch self {
        case .none: return NSLocalizedString("call.effect.none.desc", comment: "No voice modification")
        case .robot: return NSLocalizedString("call.effect.robot.desc", comment: "Metallic robotic voice")
        case .alien: return NSLocalizedString("call.effect.alien.desc", comment: "High-pitched alien voice")
        case .deep: return NSLocalizedString("call.effect.deep.desc", comment: "Deep bass voice")
        case .chipmunk: return NSLocalizedString("call.effect.chipmunk.desc", comment: "High-speed chipmunk voice")
        case .echo: return NSLocalizedString("call.effect.echo.desc", comment: "Repeating echo effect")
        case .reverb: return NSLocalizedString("call.effect.reverb.desc", comment: "Cathedral-like ambience")
        case .anonymous: return NSLocalizedString("call.effect.anonymous.desc", comment: "Completely anonymized voice")
        }
    }
}

// MARK: - Call Packet Types
enum CallPacketType: UInt8 {
    case callRequest = 0x01
    case callAccept = 0x02
    case callDecline = 0x03
    case callEnd = 0x04
    case audioData = 0x05
    case keepAlive = 0x06
    case keyExchange = 0x07
    case videoCallRequest = 0x08  // 📹 Video call request (different from voice)
    case videoCallAccept = 0x09   // 📹 Accept video call
    case callAnsweredElsewhere = 0x0A  // 📱 Call was answered on another device (multi-device)
    case requestKeyframe = 0x0B        // 📹 Request IDR keyframe from sender (decode failures)
    case videoPaused = 0x0C            // 📹 Remote camera paused (app backgrounded/PiP)
    case videoResumed = 0x0D           // 📹 Remote camera resumed (app foregrounded)
    case videoUpgrade = 0x0E           // 📹 Upgrade audio call to video (peer wants video)
    case resyncRequest = 0x0F          // 🔄 Sender just foregrounded — peer should flush its jitter buffer

    // ──────────────────────────────────────────────────────────────
    // P2P Internet Call stack — Phase 2 (reserved, not wired up yet).
    // See /Users/HUGOMORICEAU/Documents/Genesis/OSHI-P2P-PLAN.md §2.
    // ──────────────────────────────────────────────────────────────
    case iceCandidateExchange = 0x30   // 🌐 Phase 2 — exchange host/srflx/relay candidates via VPS signal
    case hdrHolePunchPing     = 0x31   // 🌐 Phase 2 — UDP hole-punch keepalive ping
    case hdrHolePunchPong     = 0x32   // 🌐 Phase 2 — UDP hole-punch keepalive ack
}

// MARK: - Connection Quality
enum ConnectionQuality: String {
    case excellent = "Excellent"   // < 50ms latency
    case good = "Good"             // 50-100ms latency
    case fair = "Fair"             // 100-200ms latency
    case poor = "Poor"             // 200-400ms latency
    case veryPoor = "Very Poor"    // > 400ms latency
    case reconnecting = "Reconnecting"
    case disconnected = "Disconnected"
    
    var icon: String {
        switch self {
        case .excellent: return "wifi.circle.fill"
        case .good: return "wifi.circle.fill"
        case .fair: return "wifi.circle"
        case .poor: return "wifi.exclamationmark"
        case .veryPoor: return "wifi.slash"
        case .reconnecting: return "arrow.triangle.2.circlepath"
        case .disconnected: return "wifi.slash"
        }
    }
    
    var color: String {
        switch self {
        case .excellent: return "green"
        case .good: return "green"
        case .fair: return "yellow"
        case .poor: return "orange"
        case .veryPoor: return "red"
        case .reconnecting: return "yellow"
        case .disconnected: return "red"
        }
    }
}

// MARK: - Call Quality Statistics
struct CallQualityStats {
    var latencyMs: Int = 0           // Current round-trip latency
    var jitterMs: Int = 0            // Variation in latency
    var packetLossPercent: Double = 0 // Packet loss percentage
    var audioPacketsSent: UInt64 = 0
    var audioPacketsReceived: UInt64 = 0
    var bytesTransmitted: UInt64 = 0
    var bytesReceived: UInt64 = 0
    var encryptionVerified: Bool = false
    var lastPingTime: Date?
    
    // 🎯 NEW: Advanced quality metrics
    var bitrateLevel: String = "Medium"       // Current adaptive bitrate level
    var jitterBufferDepthMs: Double = 0       // Current jitter buffer depth
    var packetsRecovered: UInt64 = 0          // Packets recovered via FEC
    var packetsConcealed: UInt64 = 0          // Packets concealed via PLC
    var compressionRatio: Double = 1.0        // Audio compression ratio
    var publicIP: String?                     // Discovered public IP via STUN
    
    var quality: ConnectionQuality {
        // __QUALITY_FROM_WHAT_IS_HEARD_2026_09_22__ Le badge juge ce qui
        // S'ENTEND: la latence du transport et la perte mesurée APRÈS le tampon
        // de gigue (`packetLossPercent`, part des trames masquées).
        //
        // La gigue brute n'entre plus dans les paliers. MESURÉ, appel 6216CD2F
        // du 2026-09-22, 29 min, WiFi ↔ 5G: J = 22–43 ms, rafales p95 jusqu'à
        // 300 ms — et 0,0 % de perte réseau entendue, le tampon absorbait tout.
        // C'est la 5G qui produit ces rafales, donc c'était toujours le même
        // côté (souvent celui qui décroche) qui s'affichait « mauvais » sur un
        // appel parfait. Elle ne compte plus que si elle déborde tout tampon
        // raisonnable (≥ 150 ms), et même là ne descend pas plus bas que « bon ».
        //
        // Latence: < 100 ms = excellent (demande produit). Au-delà de 400 ms la
        // valeur est un aller-retour HTTP vers le VPS, pas l'appel: ignorée.
        let latency = (latencyMs > 0 && latencyMs < 400) ? latencyMs : 0
        let loss = packetLossPercent
        if loss < 2 && latency < 100 && jitterMs < 150 { return .excellent }
        if loss < 5 && latency < 200 { return .good }
        if loss < 10 && latency < 300 { return .fair }
        if loss < 20 { return .poor }
        return .veryPoor
    }

    /// Rang pour comparer deux paliers (plus grand = meilleur).
    static func rank(_ q: ConnectionQuality) -> Int {
        switch q {
        case .excellent: return 4
        case .good: return 3
        case .fair: return 2
        case .poor: return 1
        case .veryPoor, .reconnecting, .disconnected: return 0
        }
    }
    
    var summaryString: String {
        """
        Latency: \(latencyMs)ms | Jitter: \(jitterMs)ms | Loss: \(String(format: "%.1f", packetLossPercent))%
        Bitrate: \(bitrateLevel) | Buffer: \(String(format: "%.0f", jitterBufferDepthMs))ms
        FEC Recovered: \(packetsRecovered) | PLC Concealed: \(packetsConcealed)
        """
    }
}

// MARK: - Voice Call Manager
class VoiceCallManager: NSObject, ObservableObject, @unchecked Sendable {
    static let shared = VoiceCallManager()
    
    // Published state
    /// __CALL_MINIMIZE_2026_08_16__ The call UI is a full-screen overlay at
    /// `zIndex(1000)`, so while a call is up the rest of the app is unreachable —
    /// you cannot read the address someone just sent you without hanging up.
    /// Minimizing hides that overlay and leaves a compact bar; the CALL itself is
    /// untouched, because the audio session, the transport and CallKit all live
    /// here in the manager, not in the view.
    ///
    /// It lives next to `callState` rather than in a view's `@State` on purpose:
    /// `ContentView` rebuilds the call view whenever `callViewRebuildTick` bumps
    /// (video upgrade), and a flag stored in the view would come back reset.
    @Published var isCallMinimized: Bool = false

    @Published var callState: CallState = .idle {
        didSet {
            // __PUSHKIT_OFF_MAIN_2026_09_23__ the VoIP push handler runs on the PushKit
            // queue and must not read this (main-thread) property: it reads the mirror.
            CallPushGate.shared.setCallState(callState)
            let oldStr = String(describing: oldValue)
            let newStr = String(describing: callState)
            if oldStr != newStr {
                // __CALL_MINIMIZE_2026_08_16__ Un-minimize on EVERY transition out
                // of `.inCall`. Minimizing only means anything while a call is up,
                // and this `didSet` is the one place every transition passes
                // through — so the next call cannot inherit the last one's
                // minimized state and start invisible. A flag reset at the call
                // sites instead would be a flag someone forgets at one of them.
                if callState != .inCall, isCallMinimized {
                    isCallMinimized = false
                }
                let stack = Thread.callStackSymbols.prefix(8).joined(separator: " | ")
                fileLog.logSync("🔄 STATE CHANGE: \(oldStr) → \(newStr) thread:\(Thread.isMainThread ? "main" : "bg")")
                #if os(iOS)
                // __CALL_SCREEN_BEHAVIOUR_2026_11_02__ this didSet is the one
                // place every transition passes through, so the screen rules
                // cannot be forgotten at one call site.
                applyInCallScreenBehaviour()
                #endif
                fileLog.logSync("🔄 STACK: \(stack)")
                // 🆕 Bridge to web sessions so they can render an inline call banner.
                NotificationCenter.default.post(
                    name: .init("OSHICallStateChanged"),
                    object: nil,
                    userInfo: [
                        "state": newStr,
                        "peerPublicKey": currentCallPeer ?? "",
                        "peerName": currentCallPeerName ?? "",
                        "isVideo": isCurrentCallVideo
                    ]
                )
            }
        }
    }
    @Published var isCurrentCallVideo: Bool = false {
        didSet {
            if oldValue != isCurrentCallVideo {
                let stack = Thread.callStackSymbols.prefix(8).joined(separator: " | ")
                fileLog.logSync("📹 VIDEO FLAG CHANGE: \(oldValue) → \(isCurrentCallVideo) thread:\(Thread.isMainThread ? "main" : "bg")")
                fileLog.logSync("📹 STACK: \(stack)")
            }
        }
    }
    @Published var currentCallPeer: String?
    @Published var currentCallPeerName: String?
    @Published var callDuration: TimeInterval = 0
    @Published var waitingDuration: TimeInterval = 0  // Time spent connecting/ringing
    @Published var isMuted = false
    @Published var isSpeakerOn = false
    @Published var currentEffect: CallVoiceEffect = .none
    /// Niveau de MA voix, 0…1 sur une échelle en dB (`meterLevel`).
    @Published var audioLevel: Float = 0
    /// Niveau de la voix du PAIR, 0…1, publié au moment où elle sort du
    /// haut-parleur (__VOICE_METER_2026_09_22__).
    @Published var remoteAudioLevel: Float = 0
    @Published var isOutgoingCall = false
    @Published var incomingCall: IncomingCall?
    @Published var connectionType: ConnectionType = .none
    @Published var isCallKitHandlingIncoming: Bool = false  // 🔧 FIX: Track when CallKit is showing incoming call UI

    /// 🔧 FIX (2026-07-26): the "connected" UI state is purely signalling-driven
    /// (callState = .inCall) and `connectionType` reflects ICE state, never
    /// received media — so a call with zero audio looks identical to a healthy
    /// one and nothing ever demotes. True once we have been in-call for >3 s
    /// with ZERO authenticated inbound audio packets. Call UIs should surface a
    /// distinct "no audio" state on this rather than showing "Connected".
    @Published var noInboundAudioDetected: Bool = false

    // 🔧 FIX: Centralized call deduplication - prevents multiple notification paths from handling same call
    private var activeIncomingCallId: String?
    private var activeIncomingCallSource: String?  // "voip_push", "vps_poll", "mesh"
    private let callDeduplicationLock = NSLock()
    
    // 🔧 FIX: Track when VoIP push is actively handling a call to suppress polling
    private var voipPushActiveForCaller: String?
    private var voipPushReceivedTime: Date?

    // Track if signaling is via mesh relay (audio will use VPS)
    private var usingMeshRelay = false
    
    // Audio level throttling - update UI max 10 times per second
    private var lastAudioLevelUpdate: Date = Date.distantPast
    private var lastRemoteLevelUpdate: Date = Date.distantPast
    // __VOICE_METER_2026_09_22__ 50 ms: à 10 Hz l'animation suivait les
    // syllabes avec une demi-syllabe de retard.
    private let audioLevelUpdateInterval: TimeInterval = 0.05
    
    // Connection quality metrics - Published for UI
    @Published var connectionQuality: ConnectionQuality = .good

    /// __PEER_LOST_UX_2026_09_29__ When the peer has gone silent: the moment the
    /// call will be ended for good if nothing arrives. nil while audio flows.
    /// The call screen counts down to it ("Reconnecting to Yassine…").
    @Published private(set) var peerLostDeadline: Date?
    @Published var currentLatency: Int = 0      // in milliseconds
    @Published var currentJitter: Int = 0       // in milliseconds
    @Published var qualityStats: CallQualityStats = CallQualityStats()
    @Published var lastCallEndReason: CallEndReason?  // 📱 UX: Show why call ended
    
    // Quality monitoring internals
    private var latencyHistory: [Int] = []  // Last N latency measurements
    private let latencyHistorySize = 20
    private var lastPingSentTime: Date?
    private var pingSequence: UInt32 = 0
    private var pendingPings: [UInt32: Date] = [:]  // sequence -> sent time
    private var qualityMonitorTimer: Timer?
    private var packetsSentSinceLastCheck: UInt64 = 0
    private var packetsReceivedSinceLastCheck: UInt64 = 0
    private var lastPacketLossCheck: Date = Date()
    
    // Internal counters (not @Published, can be updated from any thread)
    private var internalPacketsSent: UInt64 = 0
    private var internalPacketsReceived: UInt64 = 0
    /// 🔧 FIX: packets that ACTUALLY authenticated (AES.GCM.open succeeded).
    /// `internalPacketsReceived` increments BEFORE decryption, so a single stray
    /// or auth-failing datagram permanently disarmed the no-audio watchdog and
    /// made "we are receiving media" indistinguishable from "something hit the
    /// socket". Every media-proof decision keys on THIS counter.
    private var decryptedAudioPacketsReceived: UInt64 = 0
    /// __AUTH_FAIL_IS_NOT_NETWORK_LOSS_2026_08_27__ Paquets arrivés puis refusés
    /// par l'authentification GCM. Comptés à part, JAMAIS comme perte réseau.
    private var diagAuthFailedPackets: UInt64 = 0
    /// keepAlive reçus sur le chemin média et jetés sans PLC
    /// (__KEEPALIVE_IS_NOT_AUDIO_2026_09_22__).
    private var diagMediaKeepAlivesDropped: UInt64 = 0
    /// __QUALITY_FROM_WHAT_IS_HEARD_2026_09_22__ Trames jouées, réelles contre
    /// masquées (PLC), cumulées sur l'appel. Leur rapport sur une fenêtre EST la
    /// perte que l'utilisateur entend — après le tampon de gigue, donc sans
    /// compter la gigue que ce tampon a absorbée.
    private var qualityRealFrames: UInt64 = 0
    private var qualityConcealedFrames: UInt64 = 0
    private var qualityLastRealFrames: UInt64 = 0
    private var qualityLastConcealedFrames: UInt64 = 0
    private var qualityLossEwma: Double = 0
    /// Palier plus bas vu au dernier échantillon, pas encore affiché: il faut
    /// deux échantillons de suite (4 s) pour descendre, un seul pour remonter.
    private var qualityPendingDowngrade: ConnectionQuality?
    private var internalBytesSent: UInt64 = 0
    private var internalBytesReceived: UInt64 = 0
    
    // Deduplication flag to prevent multiple accept attempts
    /// __ACCEPT_FLAG_STRANDED_2026_08_25__ Horodaté, pour que ce drapeau ne
    /// puisse plus condamner les appels jusqu'au prochain lancement.
    ///
    /// Il garde `acceptCall()` contre une double acceptation, et il est posé à
    /// DEUX endroits — dont un hors de tout `defer`, dans une fermeture
    /// différée. Une seule sortie de cette fermeture qui oublie de le relâcher
    /// et il reste vrai pour toujours: `VoiceCallManager` est un singleton.
    /// Après ça, chaque appui sur Accepter retourne en silence sur le `guard`,
    /// sans une ligne de log, et le seul remède est de relancer l'app.
    ///
    /// C'est exactement ce qui est arrivé: appels impossibles à décrocher, puis
    /// tout refonctionne après un redémarrage, sans qu'aucun code ait changé.
    private var isAcceptingCall = false {
        didSet { isAcceptingCallSince = isAcceptingCall ? Date() : nil }
    }
    private var isAcceptingCallSince: Date?

    /// Au-delà de ça, un `isAcceptingCall` encore levé n'est plus une
    /// acceptation en cours: c'est un état oublié. Large — une acceptation
    /// normale dure moins d'une seconde, et la branche de scrutation de secours
    /// la plus lente plafonne vers 6 s.
    private let acceptFlagStaleAfter: TimeInterval = 12

    // 🔧 FIX: Track whether call was answered via CallKit (background) vs in-app overlay
    // When answered via CallKit, we must NOT dismiss CallKit - it manages the audio session
    private var wasAnsweredViaCallKit = false

    // 🔧 FIX (2026-07-26, ZERO-AUDIO): who owns AVAudioSession activation.
    // CallKit activates the session itself and signals it via `didActivate`.
    // Until that fires, ANY setActive(true) we make returns 561017449 ('!pri',
    // AVAudioSessionErrorCodeInsufficientPriority) — the system telling us to
    // wait, not an error to work around. The old code responded by calling
    // setActive(false, .notifyOthersOnDeactivation) then re-activating, which
    // RELINQUISHES the call session: the engine then runs unbound to hardware,
    // the mic tap delivers full-length all-zero buffers and playback renders
    // into nothing. Zero audio, both directions.
    //   • callKitAudioSessionActive — didActivate seen, didDeactivate not yet.
    //   • engineBuiltOnCallKitSession — the live graph was built on that session,
    //     so didDeactivate must tear it down (a graph must never outlive the
    //     session it was built on).
    private var callKitAudioSessionActive = false
    private var engineBuiltOnCallKitSession = false

    /// __ENGINE_HEALTH_NOT_ISRUNNING_2026_10_12__ `AVAudioEngine.isRunning` is not a
    /// health check, and every place that treated it as one has cost a silent call.
    ///
    /// An engine whose IO unit was built while CallKit owned a session it had not yet
    /// activated keeps reporting `isRunning == true` for the whole call while its mic
    /// tap delivers full-length all-zero buffers and its player renders into nothing.
    /// That is the "connected, nobody can hear anybody" state measured on 2026-09-25
    /// (three incoming calls: `eng=false play=false micTapReceiving=false rxPlayed=0
    /// txCount=0`, `ckActive=false`, while thousands of packets decrypted fine).
    ///
    /// `engineBuiltOnCallKitSession` records that the live graph was built on a CallKit
    /// session (`startAudioEngine`: `engineBuiltOnCallKitSession = callKitOwns`), and
    /// `callKitAudioSessionActive` records whether that session ever went live. Both
    /// together are the only honest answer to "is this running engine actually wired to
    /// the hardware?".
    private var audioEngineRunningOnLiveSession: Bool {
        VoiceCallManager.engineRunningOnLiveSession(
            isRunning: audioEngine?.isRunning == true,
            builtOnCallKitSession: engineBuiltOnCallKitSession,
            callKitSessionActive: callKitAudioSessionActive)
    }

    /// The rule above as a pure function, so it can be tested without a live call
    /// (same reason `holeCount` is static — see `CallCrashRegressionTests`).
    ///
    /// On macOS `builtOnCallKitSession` is never set, so this reduces to `isRunning`
    /// and the non-CallKit platforms keep their previous behaviour exactly.
    static func engineRunningOnLiveSession(isRunning: Bool,
                                           builtOnCallKitSession: Bool,
                                           callKitSessionActive: Bool) -> Bool {
        guard isRunning else { return false }
        // Built on a CallKit session that never got its `didActivate`: running, deaf and mute.
        if builtOnCallKitSession && !callKitSessionActive { return false }
        return true
    }

    // 🔧 FIX (2026-07-28, DND / TOTAL SILENCE): the third piece of ownership state.
    //
    // MECHANISM of the bug it closes: `callKitOwnsAudioSession` was a pure function of
    // "is this the kind of call CallKit manages", never of "did CallKit actually take
    // it". When iOS FILTERS the incoming-call report — Focus / Do Not Disturb, block
    // list — CallKit owns nothing, so `provider(_:didActivate:)` can never fire; and
    // for an outgoing call the predicate returns true unconditionally. In both cases
    // `startAudioEngine` took the "configure only, do NOT setActive" branch forever,
    // the engine was built on a session nobody ever activated, and the mic tap
    // delivered full-length all-zero buffers. Measured 2026-07-27 (iPhone 14, DND):
    // caller sent 2935 audio packets / received 1 / played 0; callee sent 0, and every
    // DIAG_PATH sample read `eng=false micRMS=0 ckActive=false ckOwns=false`. Silence
    // in both directions, with no error that says "nobody owns this".
    //
    // This flag is the ONLY thing that turns the wait into a deadline. It is set when
    // (a) CallKit tells us the report was filtered, or (b) the existing 2 s
    // `didActivate` safety net in `startAudioEngineForCall` expires. Once set,
    // `callKitOwnsAudioSession` is false and `startAudioEngine` takes the SAME branch
    // the China / callKitDisabled bypass has always used — `setActive(true)` — rather
    // than a new mechanism. It is cleared the instant `didActivate` does arrive, so a
    // late handover still wins and I1 is preserved on the normal CallKit path (which
    // was verified working on the same day: `ckOwns=true wasCallKit=true`).
    private var callKitHandoverAbandoned = false

    /// 🔧 FIX (2026-07-28) — escape hatch, default OFF (= new behaviour).
    /// Set `oshi.call.disableCallKitHandoverDeadline` to true in UserDefaults to
    /// restore the unbounded wait. It cannot help a working CallKit call — the
    /// deadline only fires once CallKit has demonstrably NOT activated — but the flag
    /// exists so the old behaviour can be restored on a device without a rebuild.
    private var callKitHandoverDeadlineEnabled: Bool {
        !UserDefaults.standard.bool(forKey: "oshi.call.disableCallKitHandoverDeadline")
    }

    /// True when CallKit is (or will be) managing this call's audio session, so
    /// startAudioEngine must NOT call setActive at all. False for the China
    /// bypass, for in-app-overlay accepts (where we dismissed CallKit and
    /// genuinely do own the session), and once the handover has been abandoned.
    private var callKitOwnsAudioSession: Bool {
        #if os(iOS)
        if callKitHandoverAbandoned { return false }
        if ChinaRegionDetector.shared.shouldBypassCallKit { return false }
        if callState == .inCall, !isOutgoingCall, !wasAnsweredViaCallKit { return false }
        return true
        #else
        return false
        #endif
    }

    /// Called by `VoIPPushManager` when `reportNewIncomingCall` completed with one of
    /// CallKit's FILTERED errors (DND / block list / restricted sharing / sensitive
    /// participants — see `VoIPPushManager.isCallKitFilterError`). CallKit is not
    /// presenting the call, so it will never activate an audio session for it: stop
    /// waiting for `didActivate` and let the app own the session.
    func callKitWillNotOwnAudio(reason: String) {
        #if os(iOS)
        guard callKitHandoverDeadlineEnabled else {
            fileLog.log("📞 CallKit will not own audio (\(reason)) — deadline DISABLED by UserDefaults, keeping the old unbounded wait")
            return
        }
        guard !callKitHandoverAbandoned else { return }
        callKitHandoverAbandoned = true
        fileLog.log("🎙️ CallKit will NOT own this call's audio (\(reason)) — the app takes the session (same path as the callKitDisabled bypass)")
        #endif
    }

    // 🔧 FIX: Track the last accepted call to prevent duplicate accepts
    private var lastAcceptedCallPeer: String?
    private var lastAcceptedCallTime: Date?
    private let acceptDeduplicationWindow: TimeInterval = 5.0  // 5 seconds window

    // 🔧 FIX: Track if user tapped CallKit accept but we're waiting for signal data
    private var pendingCallKitAccept = false
    private var pendingCallKitAcceptCallerKey: String?

    // 🔧 FIX: Track if auto-accept is scheduled (prevents manual + auto double-accept)
    private var autoAcceptScheduled = false

    // Track processed call signal IDs to prevent duplicate processing
    private var processedCallSignalIDs = Set<String>()

    // MARK: - TURN/STUN Transport Configuration
    // TURN server for relayed media transport (IP-hiding)
    // Same encrypted packets (AES-256-GCM) — just different transport layer
    struct TURNConfig {
        static let server = "turn:45.67.216.197:3478"
        // __NO_STATIC_TURN_2026_09_25__ The static credentials were removed: coturn has
        // rejected them for months (use-auth-secret), and shipping them in the binary only
        // leaked a dead secret. Calls use ephemeral creds from /voip/turn-creds.
        static let stunServer = "stun:45.67.216.197:3478"
    }

    /// Negotiated transport mode for current call.
    /// "relay" = always use relay (TURN or WebSocket), "direct" = try P2P then fallback.
    /// If EITHER party is "relay", the call uses relay transport.
    private var negotiatedPrivacyMode: String = "direct"

    /// Remote peer's privacy mode (received in call signaling)
    private var remotePrivacyMode: String?

    /// Read local call privacy setting from UserDefaults
    private var localCallPrivacyMode: String {
        return UserDefaults.standard.string(forKey: "callPrivacyMode") ?? "direct"
    }

    /// Resolve the effective transport mode based on local + remote preferences.
    /// If EITHER side wants "relay", we use relay. Only if BOTH are "direct" do we attempt P2P.
    private func resolveTransportMode(local: String, remote: String?) -> String {
        // 🔧 2026-06-29 (silent-relay fix): when the peer's privacy mode is UNKNOWN
        // (field missing — common when signaling is degraded / sig-grace strips it),
        // do NOT force relay-only. Forcing relay on an unknown peer routed calls onto
        // a relay carrier (:8089 UDP / WS) that wasn't always up → "no sound" calls.
        // Instead fall back to "direct" (P2P, still E2E-encrypted, with relay
        // fallback inside the transport). We still honour a user who EXPLICITLY chose
        // relay-only (local == "relay") for IP privacy.
        guard let remote = remote else { return local == "relay" ? "relay" : "direct" }
        if local == "direct" && remote == "direct" {
            return "direct"
        }
        return "relay"
    }

    /// Attempt to send audio/video via TURN UDP relay.
    /// Currently a placeholder — falls back to existing WebSocket transport.
    /// The TURN credentials and negotiation are in place for future UDP transport implementation.
    private func sendViaTURNRelay(data: Data) -> Bool {
        // TODO: Phase 4 — Implement actual TURN UDP transport using NWConnection
        // For now, return false to fall back to existing WebSocket transport.
        // The TURN server at 45.67.216.197:3478 is ready to accept connections.
        // Same encrypted packets — just different transport layer.
        return false
    }

    // 🔧 FIX: Track processed incoming call signals to prevent duplicate notifications
    /// (peer, callId) → first-seen time for call OFFERS. 🔧 FIX (2026-07-27): the
    /// same callRequest is routinely delivered twice — once over the call
    /// WebSocket and once by the HTTP poller — and the old peer-only dedup could
    /// not tell a re-delivery from a second, competing call. Window is 60 s to
    /// match the signal TTL; the map is trimmed to ≤32 entries.
    private var seenOfferSignatures: [String: Date] = [:]
    private var processedIncomingCallKeys = Set<String>()
    private var lastIncomingCallTime: Date?

    /// 🛟 MULTI-DEVICE FIX: callIds we've explicitly ended on THIS device.
    /// Subsequent ring signals for the SAME callId are silently dropped — this
    /// prevents the "I declined → CallKit re-rings 2s later" bug where the
    /// caller's retry/VoIP-push fanout was still landing in our queue.
    /// Entries auto-expire after 15s (see endedCallIdTTL).
    private var recentlyEndedCallIds: [String: Date] = [:]
    // 🔧 GLARE/FAST-RECALL FIX: cut 90s → 15s. A genuine fast re-dial from the same
    // peer can legitimately reuse a recently-seen callId; a 90s drop window meant
    // such a re-dial was silently swallowed by isCallIdRecentlyEnded(). 15s is still
    // long enough to absorb the caller's VoIP-push / VPS retry fanout (~8s) after a
    // hangup, but short enough not to block an intentional re-call.
    // (Per-peer keying was considered but skipped — one call site processes the
    // callId before the peer key is extracted, so threading a peer through would
    // require restructuring processCallSignal. TTL cut covers the same-peer re-dial.)
    private let endedCallIdTTL: TimeInterval = 15.0

    private func markCallIdAsEnded(_ callId: String?) {
        guard let id = callId, !id.isEmpty else { return }
        recentlyEndedCallIds[id] = Date()
        // __PUSHKIT_OFF_MAIN_2026_09_23__ same fact, readable from the PushKit queue.
        CallPushGate.shared.noteCallEnded(id, ttl: endedCallIdTTL)
        // Trim expired entries opportunistically
        let now = Date()
        recentlyEndedCallIds = recentlyEndedCallIds.filter {
            now.timeIntervalSince($0.value) < endedCallIdTTL
        }
    }

    /// __PHANTOM_RING_2026_08_27__ `internal`, pas `private`: `VoIPPushManager`
    /// doit pouvoir poser la question AVANT de faire sonner CallKit.
    ///
    /// C'est le chemin par lequel le fantôme passait. Les quatre sites qui
    /// consultaient ce garde vivent tous dans `handleIncomingCall` /
    /// `processCallSignal` — c'est-à-dire APRÈS que le signal soit arrivé par le
    /// transport. Mais une poussée VoIP en retard fait sonner CallKit sans jamais
    /// traverser ces chemins, et ses seules gardes portent sur `callState`
    /// (`.inCall`, `.connecting`, `.ringing`). À l'état `.idle` — précisément
    /// l'état d'après un raccrochage — rien ne l'arrêtait.
    ///
    /// Le journal du 27 août le montre en négatif: deux poussées pour
    /// `callId=39978481` ont été bloquées par « already ringing », et uniquement
    /// parce que l'appel sonnait encore. Arrivées une seconde plus tard, elles
    /// auraient sonné dans le vide.
    ///
    /// ⚠️ SANS RISQUE POUR LA RECONNEXION, et c'est ce qui compte ici: une
    /// reconnexion NE TERMINE PAS l'appel. `attemptWebSocketReconnect` et
    /// `attemptMeshReconnect` ne touchent ni `currentCallId` ni
    /// `recentlyEndedCallIds` — vérifié. Le `callId` d'un appel qui se rétablit
    /// n'est donc jamais marqué, et rien de ce qui le concerne n'est filtré. Le
    /// filtre porte sur l'IDENTITÉ d'un appel mort, jamais sur l'ancienneté d'un
    /// paquet ni sur l'état du réseau.
    func isCallIdRecentlyEnded(_ callId: String?) -> Bool {
        guard let id = callId, !id.isEmpty,
              let endedAt = recentlyEndedCallIds[id] else { return false }
        return Date().timeIntervalSince(endedAt) < endedCallIdTTL
    }

    // 🔧 FIX: Track when the current call session started
    // Used to reject callEnd signals that were created before this call started
    private var currentCallStartTime: Date?

    // 🔧 FIX: Track when the call was actually connected (transitioned to .inCall)
    // This is used to create a "grace period" where callEnd signals are ignored
    // to prevent race conditions where late-arriving signals end a newly connected call
    private var callConnectedTime: Date?

    // 🔧 FIX: Grace period after call connects where callEnd signals are ignored
    // This prevents stale/delayed callEnd signals from ending a just-connected call
    private let callEndGracePeriodSeconds: TimeInterval = 3.0

    // Flag to track if call was ended by remote peer (to avoid sending end signal back)
    private var receivedRemoteEndSignal = false

    // 🔧 FIX: Track if endCall is currently being processed to prevent race conditions
    private var isEndingCall = false
    private let endCallLock = NSLock()

    // 📱 MULTI-DEVICE: Unique device identifier for call routing
    // When a call is answered on one device, other devices are notified.
    // Single source of truth lives in VoIPPushManager (Keychain-backed,
    // ThisDeviceOnly) — see the comment there for the iCloud-restore bug
    // that motivated moving this off UserDefaults.
    private var deviceId: String {
        VoIPPushManager.getDeviceId()
    }

    enum ConnectionType: String {
        case none       = "none"
        case mesh       = "mesh"          // Direct P2P via MultipeerConnectivity (signaling + audio via VPS)
        case meshDirect = "mesh_direct"   // ✅ NEW: Fully offline P2P (signaling + audio via mesh)
        case tor        = "tor"           // Via Tor/VPS relay (NOT TURN — full VPS fallback path)
        case turnRelay  = "turn_relay"    // Audio flowing via TURN relay (P2PTransport state == .relay)
        case meshRelay  = "mesh_relay"    // Signaling via mesh relay, audio via VPS
        case p2p        = "p2p"           // Hole-punched UDP direct path (P2PTransport CONNECTED)

        var displayName: String {
            switch self {
            case .none: return "Not Connected"
            case .mesh: return "Mesh (VPS Audio)"
            case .meshDirect: return "📶 Mesh Direct (Offline)"
            case .tor: return "VPS Relay"
            case .turnRelay: return "TURN Relay"
            case .meshRelay: return "Mesh Relay"
            case .p2p: return "P2P"
            }
        }

        var icon: String {
            switch self {
            case .none: return "wifi.slash"
            case .mesh: return "antenna.radiowaves.left.and.right"
            case .meshDirect: return "point.3.connected.trianglepath.dotted"
            case .tor: return "network"
            case .turnRelay: return "arrow.triangle.turn.up.right.diamond"
            case .meshRelay: return "arrow.triangle.swap"
            case .p2p: return "point.3.connected.trianglepath.dotted"
            }
        }

        /// True if this connection can work without internet
        var worksOffline: Bool {
            return self == .meshDirect  // Only meshDirect is fully offline (audio via mesh)
            // meshRelay sends signaling via mesh but still needs VPS for audio
        }
    }

    // Phase 1 diagnostic: live transport path tracker.
    // Distinct from ConnectionType (logical) — TransportPath reflects which
    // physical transport actually delivered the most recent audio packet.
    // Used by the in-call UI badge so the user can see if their call is
    // riding pure P2P or has silently fallen back to a relay.
    enum TransportPath: String {
        case unknown       = "unknown"
        case p2pDirect     = "p2p_direct"      // UDP hole-punched, P2PTransport state == .connected
        case p2pTurnRelay  = "p2p_turn_relay"  // UDP via TURN allocation (P2PTransport state == .relay)
        case udpRelay      = "udp_relay"       // Our custom UDP relay (45.67.216.197:8089)
        case lanMesh       = "lan_mesh"        // Apple MultipeerConnectivity (LAN + Bluetooth, iOS↔iOS)
        case lanBridge     = "lan_bridge"      // CrossPlatformMesh TCP bridge (LAN, iOS↔Android)
        case vpsWebSocket  = "vps_websocket"   // VPS server (low latency)
        case vpsHttp       = "vps_http"        // VPS server (HTTP polling fallback)

        var displayName: String {
            switch self {
            case .unknown:       return "Connecting"
            case .p2pDirect:     return "P2P Direct"
            case .p2pTurnRelay:  return "TURN Relay"
            case .udpRelay:      return "UDP Relay"
            case .lanMesh:       return "LAN Mesh"
            case .lanBridge:     return "LAN Bridge"
            case .vpsWebSocket:  return "VPS"
            case .vpsHttp:       return "VPS (HTTP)"
            }
        }

        /// Short symbol + tier label for the UI badge.
        var symbol: String {
            switch self {
            case .unknown:       return "wifi.exclamationmark"
            case .p2pDirect:     return "lock.shield.fill"
            case .p2pTurnRelay:  return "arrow.triangle.turn.up.right.diamond.fill"
            case .udpRelay:      return "arrow.triangle.swap"
            case .lanMesh:       return "wave.3.right"
            case .lanBridge:     return "wave.3.right.circle"
            case .vpsWebSocket:  return "cloud.fill"
            case .vpsHttp:       return "cloud.bolt.fill"
            }
        }

        /// Privacy/health tier — drives badge color in the UI.
        /// .green = direct peer (no relay), .yellow = relay but encrypted, .orange = VPS server in path.
        enum Tier { case unknown, direct, relayed, server }
        var tier: Tier {
            switch self {
            case .unknown:                            return .unknown
            case .p2pDirect, .lanMesh, .lanBridge:    return .direct
            case .p2pTurnRelay, .udpRelay:            return .relayed
            case .vpsWebSocket, .vpsHttp:             return .server
            }
        }
    }

    /// Live transport path — updated whenever an audio packet is delivered.
    /// Drives the in-call UI indicator.
    @Published var activeTransport: TransportPath = .unknown

    /// 🔧 FIX (2026-07-27, "LAN Mesh badge on the cellular phone"): the badge
    /// showed a transport but never said HOW it was picked, so answering "is this
    /// call really on Bluetooth mesh?" required tailing the server. Provenance is
    /// `<path>/<why>` where why is `rx` (that path DELIVERED inside the liveness
    /// window — the honest case), `tx` (we merely handed frames to it, nothing
    /// came back) or `none`. Surfaced in DIAG_PATH as `carrier=`.
    private(set) var activeTransportProvenance: String = "unknown/none"

    /// Per-transport telemetry. Keyed by TransportPath. Values: (rxPackets, rxBytes, txPackets, txBytes, lastRxAt).
    struct TransportStats {
        var rxPackets: UInt64 = 0
        var rxBytes: UInt64 = 0
        var txPackets: UInt64 = 0
        var txBytes: UInt64 = 0
        var lastRxAt: Date?
        var lastTxAt: Date?
    }

    // ⚠️ Kill switch for Phase 1 transport telemetry. If `false`, recordRx/recordTx
    // become no-ops, the refresh timer never installs, and `activeTransport` stays
    // .unknown. Useful to bisect freeze/regression suspicions: flip to `false`,
    // rebuild, retest — if the symptom disappears, the bug is in the telemetry
    // (recordRx, recordTx, refresh timer, or sheet). If it persists, look elsewhere.
    private static let transportTelemetryEnabled: Bool = true

    // ⚠️ NOT @Published — mutated from audio capture/network background threads
    // at ~250 events/sec (5 transports × 50 packets/sec). Publishing every
    // mutation saturated MainActor and froze the call UI (timer stopped,
    // end-call button unresponsive). The UI reads via snapshotTransportStats()
    // through a 1 Hz timer in the details sheet instead.
    private var _transportStats: [TransportPath: TransportStats] = [:]
    private let transportStatsLock = NSLock()

    /// Snapshot of the current per-transport stats. Safe to call from any thread.
    func snapshotTransportStats() -> [TransportPath: TransportStats] {
        transportStatsLock.lock()
        let copy = _transportStats
        transportStatsLock.unlock()
        return copy
    }

    /// Marks a packet as received via `path`. Thread-safe.
    /// Does NOT touch any @Published property — the shotgun-broadcast design
    /// means audio is received via 3+ transports in parallel, which would
    /// generate 150+ MainActor dispatches per second per device (saturated
    /// the A15 in iPhone 14 and froze the call UI). The @Published
    /// `activeTransport` is instead refreshed by a 1 Hz MainActor timer
    /// that picks the highest-priority active path — see startTransportRefreshTimer().
    fileprivate func recordRx(_ path: TransportPath, bytes: Int) {
        guard Self.transportTelemetryEnabled else { return }
        transportStatsLock.lock()
        var s = _transportStats[path] ?? TransportStats()
        s.rxPackets &+= 1
        s.rxBytes &+= UInt64(bytes)
        s.lastRxAt = Date()
        _transportStats[path] = s
        transportStatsLock.unlock()
    }

    fileprivate func recordTx(_ path: TransportPath, bytes: Int) {
        guard Self.transportTelemetryEnabled else { return }
        transportStatsLock.lock()
        var s = _transportStats[path] ?? TransportStats()
        s.txPackets &+= 1
        s.txBytes &+= UInt64(bytes)
        s.lastTxAt = Date()
        _transportStats[path] = s
        transportStatsLock.unlock()
    }

    fileprivate func resetTransportStats() {
        transportStatsLock.lock()
        _transportStats.removeAll()
        transportStatsLock.unlock()
        DispatchQueue.main.async { [weak self] in
            self?.activeTransport = .unknown
        }
    }

    // Priority order (best path first) for choosing which transport to surface
    // in the UI when multiple are delivering simultaneously. Direct peer-to-peer
    // beats relays; relays beat the VPS server.
    private static let transportPriority: [TransportPath] = [
        .p2pDirect, .lanMesh, .lanBridge,
        .p2pTurnRelay, .udpRelay,
        .vpsWebSocket, .vpsHttp
    ]
    private static let transportLivenessWindow: TimeInterval = 2.0

    private var transportRefreshTimer: Timer?

    /// Starts the 1 Hz refresh that keeps `activeTransport` in sync with the
    /// currently-live highest-priority transport. Called when the call enters
    /// .connecting / .inCall.
    fileprivate func startTransportRefreshTimer() {
        guard Self.transportTelemetryEnabled else { return }
        let install: () -> Void = { [weak self] in
            guard let self = self else { return }
            self.transportRefreshTimer?.invalidate()
            let timer = Timer(timeInterval: 1.0, repeats: true) { [weak self] _ in
                self?.refreshActiveTransport()
            }
            RunLoop.main.add(timer, forMode: .common)
            self.transportRefreshTimer = timer
        }
        if Thread.isMainThread { install() } else { DispatchQueue.main.async(execute: install) }
    }

    fileprivate func stopTransportRefreshTimer() {
        // Timer must be invalidated on the run loop it was scheduled on (main).
        // cleanup() may be called from background contexts, so hop to MainActor.
        if Thread.isMainThread {
            transportRefreshTimer?.invalidate()
            transportRefreshTimer = nil
        } else {
            DispatchQueue.main.async { [weak self] in
                self?.transportRefreshTimer?.invalidate()
                self?.transportRefreshTimer = nil
            }
        }
    }

    private func refreshActiveTransport() {
        let snapshot = snapshotTransportStats()
        let now = Date()
        let window = Self.transportLivenessWindow
        // Pick the highest-priority transport with recent TX *or* RX activity.
        // WHY: when P2P is asymmetric (one side stuck in `probing`, the other
        // in `relay`), one direction may go through P2P while the other falls
        // back to VPS. Counting only RX made the badge show "VPS" on the P2P
        // side even though we were sending over P2P. Considering both sides
        // surfaces the better of the two, which matches user expectation:
        // "we're using P2P" if any direction is P2P.
        //
        // 🔧 FIX (2026-07-27, "badge flaps at 50 Hz"): rank DELIVERY first.
        // The old `rxFresh || txFresh` treated a path we merely sent down as
        // equal to one that is landing frames, so while sendAudioPacket was
        // shotgunning udp_relay + WS the badge alternated between "UDP Relay"
        // and "VPS" continuously and read as instability. (It was not path
        // oscillation — `txPath` changed twice in 42 DIAG_PATH samples on one
        // device and zero times on the other; `p2pCanCarryAudio()` is stable.)
        // Two passes: anything receiving wins; TX-only is the fallback so the
        // asymmetric case below still surfaces the better direction.
        let rxChosen = Self.transportPriority.first(where: { path in
            snapshot[path]?.lastRxAt.map { now.timeIntervalSince($0) < window } ?? false
        })
        let txChosen = Self.transportPriority.first(where: { path in
            snapshot[path]?.lastTxAt.map { now.timeIntervalSince($0) < window } ?? false
        })
        let chosen: TransportPath = rxChosen ?? txChosen ?? .unknown
        // 🔧 FIX (2026-07-27): record WHY, not just WHAT. `rx` = that path handed
        // us media; `tx` = we only handed media to it (a MultipeerConnectivity
        // `send` to a "connected" peer succeeds locally even when the peer's app
        // never sees the frame, which is exactly how a badge can name a transport
        // that carried nothing).
        let provenance = "\(chosen.rawValue)/\(rxChosen != nil ? "rx" : (txChosen != nil ? "tx" : "none"))"
        if activeTransport != chosen || activeTransportProvenance != provenance {
            let line = "DIAG_TRANSPORT_BADGE | \(activeTransportProvenance) -> \(provenance)"
                + " | txPrimary=\(txPrimaryCurrent?.rawValue ?? "none")"
                + " | net=cell=\(currentNetFlags().cellular)"
            OshiLog.call.info("\(line)"); fileLog.log(line)
            activeTransportProvenance = provenance
            activeTransport = chosen
        }
    }

    // Internet reachability check
    @Published var hasInternetConnection: Bool = true
    private var networkMonitor: NWPathMonitor?
    
    // MARK: - VPS Configuration
    // The VPS relays encrypted voice data - all traffic is E2E encrypted (AES-256-GCM)
    // The VPS only sees encrypted blobs - it cannot decrypt the audio
    private let vpsPublicURL = "https://oshi-messenger.com"

    // VoIP path prefix - routes through nginx (HTTPS on 443) → proxy to VoIP server (HTTP on 8083)
    // 🔧 FIX: Direct port 8083 fails because VoIP server is plain HTTP but iOS requires HTTPS
    private let vpsVoIPPath = "/voip"

    private var currentVPSURL: String {
        return vpsPublicURL
    }

    // Computed URLs for different services - all route through nginx HTTPS
    private var vpsURL: String {
        return currentVPSURL + vpsVoIPPath  // e.g. https://oshi-messenger.com/voip
    }

    private var vpsWebSocketURL: String {
        let wsScheme = currentVPSURL.hasPrefix("https") ? "wss" : "ws"
        let host = currentVPSURL
            .replacingOccurrences(of: "http://", with: "")
            .replacingOccurrences(of: "https://", with: "")
        // 🔧 FIX: nginx location block is "location /voip/" (with trailing slash).
        // Without trailing slash, the WS upgrade request does NOT match the location block,
        // falling through to a default handler without proper proxy timeouts/buffering settings.
        // This caused the WebSocket to die after ~5 seconds of heavy video traffic.
        return "\(wsScheme)://\(host)\(vpsVoIPPath)/"
    }

    private var vpsBaseURL: String {
        return currentVPSURL + vpsVoIPPath
    }
    
    // MARK: - Base64URL Encoding/Decoding Helpers
    // 🔧 CRITICAL: Use base64url encoding for public keys in URLs
    // Standard base64 uses +/= which break URL paths even when percent-encoded
    // Base64url uses -_ instead and is URL-safe
    private func base64urlEncode(_ string: String) -> String {
        return string
            .replacingOccurrences(of: "+", with: "-")
            .replacingOccurrences(of: "/", with: "_")
            .replacingOccurrences(of: "=", with: "")
    }

    // 🔧 CRITICAL FIX: Decode base64url back to standard base64
    // VPS returns keys in base64url format, but Data(base64Encoded:) expects standard base64
    private func base64urlDecode(_ base64urlString: String) -> String {
        var result = base64urlString
            .replacingOccurrences(of: "-", with: "+")
            .replacingOccurrences(of: "_", with: "/")
        // Add padding if needed
        while result.count % 4 != 0 {
            result.append("=")
        }
        return result
    }
    
    /// Add Ed25519 signature headers to an HTTP request for server-side verification.
    /// __CALL_PUSH_AUTH_IOS_2026_09_23__ Every call_server / push_service request goes through
    /// ``CallPushSigner`` (docs/CALL_PUSH_AUTH_CONTRACT.md): Keychain `signingKey` = the key
    /// bound to our identity by v2 publication, path as sent (percent-encoded, trailing slash
    /// kept, query excluded), `httpBody` bytes as sent. Was: `IdentityManager.signingPrivateKey`
    /// + `url.path` — same key in practice, but `url.path` drops the trailing slash.
    @discardableResult
    private func signRequest(_ request: inout URLRequest) -> Bool {
        CallPushSigner.sign(&request)
    }

    /// Add signature fields to a WebSocket JSON message (mutates the dictionary)
    private func signWebSocketMessage(_ message: inout [String: Any], type: String) {
        guard let identityManager = getIdentityManager() else { return }

        let payloadObj: [String: Any] = {
            var obj = [String: Any]()
            if let audio = message["audio"] { obj["audio"] = audio }
            if let signal = message["signal"] { obj["signal"] = signal }
            if let recipient = message["recipient"] { obj["recipient"] = recipient }
            if let callId = message["callId"] { obj["callId"] = callId }
            return obj
        }()

        guard let payloadData = try? JSONSerialization.data(withJSONObject: payloadObj, options: .sortedKeys) else { return }
        let hashStr = SHA256.hash(data: payloadData).compactMap { String(format: "%02x", $0) }.joined()

        if let sig = identityManager.signWebSocketMessage(type: type, payloadHash: hashStr) {
            message["signature"] = sig.signature
            message["wsTimestamp"] = sig.timestamp
            message["signingPubKey"] = sig.signingPublicKey
        }
    }

    // Optimized URLSession for low-latency audio
    private lazy var audioURLSession: URLSession = {
        let config = URLSessionConfiguration.ephemeral  // No caching
        config.timeoutIntervalForRequest = 2.0  // 🔧 FIX: 300ms was too aggressive — caused mass "request aborted" on server
        config.timeoutIntervalForResource = 5.0
        config.requestCachePolicy = .reloadIgnoringLocalAndRemoteCacheData
        config.urlCache = nil
        // 🔧 FIX: Increased from 6 to 10 — send + receive share this session
        config.httpMaximumConnectionsPerHost = 10
        config.httpShouldUsePipelining = true
        config.httpShouldSetCookies = false  // No cookies needed
        config.httpCookieAcceptPolicy = .never
        return URLSession(configuration: config)
    }()

    /// Dedicated session for the `/health` latency probe.
    ///
    /// Kept apart from `audioURLSession` on purpose: sharing it meant the probe
    /// competed for the same 10-connection HTTP/1.1 pool as the 20 Hz audio
    /// poller and timed out against a healthy server. Two connections is ample
    /// for one request every 2 s, and the generous timeout is affordable now
    /// that a single failure no longer means anything on its own.
    private lazy var latencyProbeSession: URLSession = {
        let config = URLSessionConfiguration.ephemeral
        config.timeoutIntervalForRequest = 3.0
        config.timeoutIntervalForResource = 5.0
        config.requestCachePolicy = .reloadIgnoringLocalAndRemoteCacheData
        config.urlCache = nil
        config.httpMaximumConnectionsPerHost = 2
        config.httpShouldSetCookies = false
        return URLSession(configuration: config)
    }()

    // WebSocket connection for real-time audio
    private var webSocket: URLSessionWebSocketTask?
    private var webSocketSession: URLSession?
    private var isWebSocketConnected = false

    /// 🔧 FIX (2026-07-27) — "the dial path must never be able to wait on socket setup".
    ///
    /// MEASURED (owner's iPhone 17 Pro Max, cellular, call 8FE00951 at 15:02:55Z):
    /// `startCall` logged `🔌 WS-on-dial` and NOTHING was ever written to the log
    /// again — no `🔄 STATE CHANGE: idle → connecting` (a healthy dial 58 min earlier
    /// emits it in the same second), no CallKit report, no signal fan-out, so the
    /// callee never rang. The process stayed alive; there was no 0x8BADF00D.
    ///
    /// MECHANISM: `startCall` is a `nonisolated async` method, so per SE-0338 its body
    /// runs on a Swift-concurrency COOPERATIVE thread. It called `connectWebSocket()`
    /// synchronously there. Socket setup is not bounded work — it opens with
    /// `getIdentityManager()` (Keychain / `securityd` XPC on a cold cache), then tears
    /// down any leftover `URLSession` and builds a new one on a constrained cellular
    /// path. Blocking a cooperative thread is not a local cost: the pool is only as
    /// wide as the core count, and the very first statement of
    /// `checkForIncomingCallSignals` — which runs as a fresh `Task` once a second — is
    /// that SAME `getIdentityManager()` call. Within a second or two every cooperative
    /// thread was parked in the same place, so `MessageManager.pollSingleQueue`'s
    /// continuation could not resume either: its `DIAG_VPS_POLL_REQ` at 15:02:55Z has
    /// no matching `DIAG_VPS_POLL_RESP`, and both 1 Hz poll loops go silent from that
    /// instant. That is the fingerprint of pool starvation, not of one stuck task.
    ///
    /// FIX: socket setup runs on a DEDICATED serial queue. It is still eager — the
    /// 11 s late-socket problem that WS-on-dial was introduced to solve is unchanged,
    /// the handshake still starts at dial time rather than at answer time — but a slow
    /// handshake can now only ever stall this one private thread. Signalling, CallKit
    /// and audio capture proceed regardless of how long it takes.
    private let wsSetupQueue = DispatchQueue(label: "com.oshi.call.wssetup", qos: .userInitiated)

    /// Eagerly open the VPS signalling socket WITHOUT blocking the caller.
    /// Used by both the dial path (`startCall`) and the ring path
    /// (`setupIncomingCallFromPush` — a PushKit callback, where blocking is worse
    /// still: iOS kills the app for not reporting a call in time).
    private func openSignallingSocketAsync(reason: String) {
        // Escape hatch: `oshi.call.blockingWsOnDial` = true restores the old
        // synchronous behaviour. Default (false) is the safe, non-blocking path.
        if UserDefaults.standard.bool(forKey: "oshi.call.blockingWsOnDial") {
            fileLog.log("🔌 WS-\(reason): opening VPS WebSocket SYNCHRONOUSLY (oshi.call.blockingWsOnDial=true)")
            connectWebSocket()
            return
        }
        let expectedCallId = currentCallId
        fileLog.log("🔌 WS-\(reason): dispatching VPS WebSocket setup off the caller's thread")
        wsSetupQueue.async { [weak self] in
            guard let self = self else { return }
            // The call may have ended (or a new one started) while we were queued.
            guard self.currentCallId == expectedCallId else {
                fileLog.log("🔌 WS-\(reason): skipped — callId changed before setup ran")
                return
            }
            guard !self.isWebSocketConnected else {
                fileLog.log("🔌 WS-\(reason): skipped — socket already live")
                return
            }
            let t0 = Date()
            self.connectWebSocket()
            let ms = Int(Date().timeIntervalSince(t0) * 1000)
            fileLog.log("🔌 WS-\(reason): connectWebSocket() returned after \(ms) ms (off the dial path)")
        }
    }

    /// Cancel + invalidate a WebSocket/URLSession pair without blocking the caller.
    /// `invalidateAndCancel()` waits on in-flight tasks and delegate callbacks, and
    /// teardown is reached from the WS processing queue (`endCall` ← `handleWebSocketMessage`)
    /// and from cooperative threads (`startCall`). Neither may pay that cost inline.
    private func teardownWebSocketAsync(task: URLSessionWebSocketTask?,
                                        session: URLSession?,
                                        closeCode: URLSessionWebSocketTask.CloseCode,
                                        reason: String) {
        guard task != nil || session != nil else { return }
        if UserDefaults.standard.bool(forKey: "oshi.call.blockingWsTeardown") {
            task?.cancel(with: closeCode, reason: nil)
            session?.invalidateAndCancel()
            return
        }
        wsSetupQueue.async {
            task?.cancel(with: closeCode, reason: nil)
            session?.invalidateAndCancel()
            fileLog.log("🔌 WS teardown(\(reason)): socket cancelled + session invalidated off-thread")
        }
    }

    /// `isOutgoingConnecting` is `@Published`. Writing it from a background thread
    /// publishes into SwiftUI from that thread — see `setOutgoingConnecting`.
    private func setOutgoingConnecting(_ value: Bool) {
        if Thread.isMainThread {
            isOutgoingConnecting = value
        } else {
            DispatchQueue.main.async { [weak self] in
                self?.isOutgoingConnecting = value
            }
        }
    }


